/* Opt-in Atomic UI primitives. Every visual contract is attached to ui-* markup.

   Fase 3: every spacing / font-size / font-weight / radius value here comes
   from the Fase 1 scales in 00_tokens.css. Raw px is allowed only for the
   few values that are control affordances rather than rhythm (control
   heights, the search-icon box, the select chevron gutter) and for
   line-height, which has no token scale yet. Keep it that way -- the point
   of the scope is that Fase 5 can restyle it by changing token values.
   See RINCIAN_AUDIT_UI_UX_CSS_ERP_IDHA_BOGA.md, Fase 3. */

.ui-scope {
    /* Reads the light/dark contract from 100_theme_black_white_lock.css
       (--success/--warning/--danger/--info/--text-*/--surface/--border) so
       .ui-scope components follow theme switches automatically instead of
       needing their own [data-theme="dark-mono"] overrides. The literal
       fallback after each comma is only used if that theme token is ever
       missing -- it is the original hardcoded value this replaced. */
    --ui-primary: var(--success, #166534);
    --ui-primary-hover: var(--success, #14532d);
    --ui-primary-soft: var(--success-soft, #f0fdf4);
    --ui-warning: var(--warning, #b45309);
    --ui-warning-soft: var(--warning-soft, #fffbeb);
    --ui-danger: var(--danger, #b91c1c);
    --ui-danger-hover: var(--danger, #991b1b);
    --ui-danger-soft: var(--danger-soft, #fef2f2);
    --ui-info: var(--info, #1d4ed8);
    --ui-info-soft: var(--info-soft, #eff6ff);
    --ui-neutral: var(--text-secondary, #475569);
    --ui-neutral-soft: var(--surface-muted, #f8fafc);
    --ui-text: var(--text-primary, #172033);
    --ui-text-muted: var(--text-muted, #64748b);
    --ui-surface: var(--surface, #ffffff);
    --ui-surface-muted: var(--surface-muted, #f8fafc);
    --ui-border: var(--border, #d7dee8);
    --ui-border-strong: var(--border, #bdc7d5);
    --ui-radius: var(--radius-sm, 8px);
    /* Control heights are affordances, not spacing rhythm: they are sized to
       a comfortable touch target, so they stay off the 4px scale on purpose. */
    --ui-control-height: 42px;
    --ui-control-height-compact: 40px;
    --ui-icon-size: 18px;
    min-width: 0;
    color: var(--ui-text);
}

.ui-scope .ui-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    min-width: 40px;
    min-height: var(--ui-control-height);
    margin: 0;
    padding: 0 var(--space-4);
    border: 1px solid transparent;
    border-radius: var(--ui-radius);
    font: inherit;
    font-size: var(--font-sm);
    font-weight: var(--fw-bold);
    line-height: 1;
    letter-spacing: 0;
    text-align: center;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.ui-scope .ui-button--compact {
    min-height: var(--ui-control-height-compact);
    padding-inline: var(--space-3);
    font-size: var(--font-xs);
}

.ui-scope .ui-button--primary {
    border-color: var(--ui-primary);
    background: var(--ui-primary);
    color: #ffffff;
}

.ui-scope .ui-button--primary > .ui-button-label,
.ui-scope .ui-button--primary > i,
.ui-scope .ui-button--danger > .ui-button-label,
.ui-scope .ui-button--danger > i {
    color: #ffffff;
}

.ui-scope .ui-button--secondary > .ui-button-label,
.ui-scope .ui-button--secondary > i,
.ui-scope .ui-button--ghost > .ui-button-label,
.ui-scope .ui-button--ghost > i {
    color: inherit;
}

.ui-scope .ui-button--primary:hover,
.ui-scope .ui-button--primary:focus-visible {
    border-color: var(--ui-primary-hover);
    background: var(--ui-primary-hover);
    color: #ffffff;
}

.ui-scope .ui-button--secondary {
    border-color: var(--ui-border-strong);
    background: var(--ui-surface);
    color: var(--ui-text);
}

.ui-scope .ui-button--secondary:hover,
.ui-scope .ui-button--secondary:focus-visible {
    border-color: var(--ui-neutral);
    background: var(--ui-neutral-soft);
    color: var(--ui-text);
}

.ui-scope .ui-button--ghost {
    border-color: transparent;
    background: transparent;
    color: var(--ui-neutral);
}

.ui-scope .ui-button--ghost:hover,
.ui-scope .ui-button--ghost:focus-visible {
    border-color: var(--ui-border);
    background: var(--ui-neutral-soft);
    color: var(--ui-text);
}

.ui-scope .ui-button--danger {
    border-color: var(--ui-danger);
    background: var(--ui-danger);
    color: #ffffff;
}

.ui-scope .ui-button--danger:hover,
.ui-scope .ui-button--danger:focus-visible {
    border-color: var(--ui-danger-hover);
    background: var(--ui-danger-hover);
    color: #ffffff;
}

.ui-scope .ui-button:focus-visible,
.ui-scope .ui-control:focus-visible,
.ui-scope .ui-select-trigger:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--ui-info) 24%, transparent);
    outline-offset: 2px;
}

.ui-scope .ui-button[aria-disabled="true"],
.ui-scope .ui-button:disabled {
    opacity: 0.58;
    cursor: not-allowed;
}

.ui-scope .ui-field {
    display: grid;
    min-width: 0;
    gap: var(--space-2);
    text-align: left;
}

.ui-scope .ui-field-label {
    margin: 0;
    color: var(--ui-text-muted);
    font-size: var(--font-xs);
    font-weight: var(--fw-bold);
    line-height: 16px;
    text-align: left;
}

.ui-scope .ui-control {
    width: 100%;
    min-width: 0;
    min-height: var(--ui-control-height);
    padding: 0 var(--space-3);
    border: 1px solid var(--ui-border-strong);
    border-radius: var(--ui-radius);
    background: var(--ui-surface);
    color: var(--ui-text);
    font: inherit;
    font-size: var(--font-sm);
    line-height: 20px;
    letter-spacing: 0;
    text-align: left;
}

.ui-scope .ui-control::placeholder {
    color: var(--ui-text-muted);
    opacity: 1;
}

.ui-scope .ui-search-field {
    min-width: 0;
}

.ui-scope .ui-search-control {
    position: relative;
    min-width: 0;
}

.ui-scope .ui-search-icon {
    position: absolute;
    top: 50%;
    left: var(--space-3);
    z-index: 1;
    width: var(--ui-icon-size);
    height: var(--ui-icon-size);
    color: var(--ui-text-muted);
    line-height: var(--ui-icon-size);
    text-align: center;
    pointer-events: none;
    transform: translateY(-50%);
}

.ui-scope .ui-search-input {
    /* Derived from the icon box so the two can never drift: gutter + icon + gutter. */
    padding-left: calc(var(--space-3) * 2 + var(--ui-icon-size));
}

.ui-scope .ui-select {
    position: relative;
    min-width: 0;
}

.ui-scope .ui-select-control {
    appearance: none;
    /* Chevron gutter -- an affordance sized to the glyph, not spacing rhythm. */
    padding-right: 40px;
    text-align: left;
}

.ui-scope .ui-select-trigger {
    display: flex;
    align-items: center;
    width: 100%;
    min-height: var(--ui-control-height);
    justify-content: flex-start;
    gap: var(--space-2);
    padding: 0 var(--space-2) 0 var(--space-3);
    border: 1px solid var(--ui-border-strong);
    border-radius: var(--ui-radius);
    background: var(--ui-surface);
    color: var(--ui-text);
    font-size: var(--font-sm);
    text-align: left;
}

.ui-scope .ui-select-value {
    min-width: 0;
    margin-right: auto;
    overflow: hidden;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ui-scope .ui-select-chevron {
    flex: 0 0 30px;
    margin-left: auto;
}

/* The menu and the popover below are moved to <body> by main.js, so they sit
   outside .ui-scope and cannot read the --ui-* variables. The literal after
   each comma is the fallback that actually applies there. The --space-* /
   --font-* / --radius-* tokens need no fallback: they are declared on :root. */
.ui-select-menu {
    z-index: 2140;
    max-height: calc(100vh - var(--space-6));
    max-width: calc(100vw - var(--space-6));
    overflow: auto;
    padding: var(--space-2);
    border: 1px solid var(--ui-border, #d7dee8);
    border-radius: var(--ui-radius, 8px);
    background: var(--ui-surface, #ffffff);
    color: var(--ui-text, #172033);
    box-shadow: 0 16px 36px rgba(15, 23, 42, 0.14);
    text-align: left;
}

.ui-select-menu[hidden] {
    display: none;
}

.ui-select-menu .ui-select-search-wrap {
    padding: 0 0 var(--space-2);
}

.ui-select-menu .ui-select-search {
    width: 100%;
    min-height: 40px;
    padding: 0 var(--space-3);
    border: 1px solid var(--ui-border-strong, #b9c4d3);
    border-radius: var(--ui-radius, 8px);
    background: var(--ui-surface, #ffffff);
    color: var(--ui-text, #172033);
    font: inherit;
    text-align: left;
}

.ui-select-menu .ui-select-options {
    max-height: min(320px, 48vh);
    overflow: auto;
}

.ui-select-menu .ui-select-search,
.ui-select-menu .ui-select-option,
.ui-select-menu .ui-select-option-label {
    text-align: left;
}

.ui-select-menu .ui-select-option {
    display: flex;
    align-items: center;
    width: 100%;
    min-height: 40px;
    margin: 0 0 var(--space-1);
    justify-content: flex-start;
    padding: var(--space-2) var(--space-3);
    border: 0;
    border-radius: var(--ui-radius, 8px);
    background: var(--ui-surface, #ffffff);
    color: var(--ui-text, #172033);
    cursor: pointer;
    font: inherit;
    font-weight: var(--fw-semibold);
}

.ui-select-menu .ui-select-option:hover,
.ui-select-menu .ui-select-option:focus-visible {
