.ui-scope .ui-data-table .ui-table-head-cell.ui-table-cell--sticky-code,
.ui-scope .ui-data-table .ui-table-head-cell.ui-table-cell--sticky-name,
.ui-scope .ui-data-table .ui-table-head-cell.ui-table-cell--sticky-actions {
