/* ==================================================
   UI — Dashboard Chart UI Partial
   Owner/Admin read-only analytics chart cards.
   No new color hardcode: all visual tones inherit theme tokens.
   ================================================== */
.dashboard-analytics-section {
    scroll-margin-top: 88px;
}

.dashboard-analytics-header {
    align-items: flex-start;
}

.dashboard-period-chip {
    min-height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 6px 11px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-badge);
    background: var(--surface-soft);
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}

.dashboard-analytics-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(300px, 0.85fr);
    gap: var(--card-gap);
    align-items: stretch;
}

.dashboard-analytics-card,
.dashboard-chart-card {
    min-width: 0;
    background: var(--surface);
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-card);
    box-shadow: var(--shadow-sm);
    padding: var(--card-padding);
    overflow: hidden;
}

.dashboard-chart-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 16px;
}

.dashboard-chart-card-header h3 {
    margin: 0;
    color: var(--text-primary);
    font-size: 17px;
    font-weight: 700;
}

.dashboard-chart-card-header p {
    margin: 4px 0 0;
    color: var(--text-muted);
    font-size: 13px;
    line-height: 1.45;
}

.dashboard-chart-menu .btn-icon {
    width: 38px;
    height: 38px;
    padding: 0;
    border-radius: var(--radius-button-sm);
}

.dashboard-bar-chart {
    min-width: 0;
}

.dashboard-bar-plot {
    height: 260px;
    display: grid;
    grid-template-columns: repeat(12, minmax(28px, 1fr));
    align-items: end;
    gap: 10px;
    padding: 18px 4px 8px;
    border-radius: var(--radius-card);
    background: linear-gradient(180deg, var(--surface-soft), var(--surface));
    border: 1px solid var(--border-soft);
    overflow-x: auto;
    scrollbar-width: thin;
}

.dashboard-bar-group {
    min-width: 28px;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
}

.dashboard-bar-pair {
    width: 100%;
    min-height: 190px;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 4px;
}

.dashboard-bar {
    width: min(16px, 46%);
    min-height: 4px;
    height: max(4px, var(--bar-height));
    border-radius: 999px 999px 5px 5px;
    display: block;
    transition: transform .18s ease, opacity .18s ease;
}

.dashboard-bar:hover,
.dashboard-bar:focus-visible {
    opacity: .86;
    transform: translateY(-2px);
    outline: 2px solid var(--border);
    outline-offset: 2px;
}

.dashboard-bar-revenue {
    background: var(--info);
}

.dashboard-bar-spending {
    background: var(--primary);
}

.dashboard-bar-label {
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
}

.dashboard-chart-legend {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 14px;
    margin-top: 12px;
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 700;
}

.dashboard-chart-legend span,
.dashboard-donut-metric span {
    display: inline-flex;
    align-items: center;
    gap: 7px;
}

.dashboard-legend-dot {
    width: 10px;
    height: 10px;
    display: inline-block;
    border-radius: var(--radius-badge);
    background: var(--info);
    flex: 0 0 auto;
}

.dashboard-legend-spending,
.dashboard-donut-metric-late .dashboard-legend-dot {
    background: var(--primary);
}

.dashboard-donut-metric-issue_shortage .dashboard-legend-dot {
    background: var(--warning);
}

.dashboard-donut-metric small {
    display: block;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .02em;
}

.dashboard-donut-chart {
    width: min(230px, 72vw);
    aspect-ratio: 1;
    border-radius: 50%;
    display: grid;
    place-items: center;
    text-decoration: none;
    background: conic-gradient(
        var(--info) 0 var(--donut-on-time),
        var(--primary) var(--donut-on-time) var(--donut-late-stop),
        var(--warning) var(--donut-late-stop) 100%
    );
    box-shadow: var(--shadow-sm);
}

.dashboard-donut-chart:hover,
.dashboard-donut-chart:focus-visible {
    transform: translateY(-1px);
    outline: 3px solid var(--border);
    outline-offset: 4px;
}

.dashboard-donut-hole {
    width: 58%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: var(--surface);
    border: 1px solid var(--border-soft);
    display: grid;
    place-items: center;
    align-content: center;
    text-align: center;
    padding: 14px;
}

.dashboard-donut-hole strong {
    color: var(--text-primary);
    font-size: clamp(28px, 5vw, 42px);
    font-weight: 700;
    line-height: 1;
}

.dashboard-donut-hole small {
    margin-top: 6px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 700;
}

.dashboard-donut-metrics {
    display: grid;
    gap: 10px;
}

.dashboard-donut-metric {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 4px 10px;
    align-items: center;
    min-height: 58px;
    padding: 11px 12px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-button);
    background: var(--surface-soft);
    color: var(--text-secondary);
    text-decoration: none;
}

.dashboard-donut-metric strong {
    color: var(--text-primary);
    font-size: 16px;
    font-weight: 700;
}

.dashboard-donut-metric small {
    grid-column: 1 / -1;
    text-transform: none;
    letter-spacing: 0;
}

.dashboard-chart-empty {
    min-height: 260px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
}

@media (max-width: 1199.98px) {
    .dashboard-analytics-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 767.98px) {
    .dashboard-analytics-header,
    .dashboard-chart-card-header {
        flex-direction: column;
    }

    .dashboard-period-chip {
        width: 100%;
    }

    .dashboard-analytics-card,
    .dashboard-chart-card {
        padding: 16px;
    }

    .dashboard-bar-plot {
        grid-template-columns: repeat(12, minmax(34px, 1fr));
        height: 230px;
        gap: 8px;
    }

    .dashboard-bar-pair {
        min-height: 160px;
    }

    .dashboard-donut-metric {
        min-height: 54px;
    }
}


