/* ==================================================
   UI Typography & Theme Token Refresh
   Scope: font scale, color maturity, readable KPI/table/form typography.
   Rules: token-first, no database/business logic impact.
   ================================================== */
:root {
    --font-sans: "Inter", "Manrope", "Plus Jakarta Sans", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    --font-number: "Inter", "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

    --font-weight-body: 450;
    --font-weight-medium: 620;
    --font-weight-strong: 740;
    --font-weight-title: 800;
    --font-weight-number: 820;

    --text-xs: 11px;
    --text-sm: 12px;
    --text-base: 14px;
    --text-table: 13px;
    --text-card-title: 15px;
    --text-section-title: 18px;
    --text-page-title: 24px;
    --text-page-title-mobile: 21px;
    --text-kpi-number: 28px;
    --text-kpi-number-mobile: 24px;

    --line-tight: 1.15;
    --line-title: 1.22;
    --line-body: 1.55;
    --letter-title: -0.03em;
    --letter-label: 0.075em;

    --sidebar: #071426;
    --sidebar-active: #132642;
    --sidebar-hover: color-mix(in srgb, var(--accent) 18%, transparent);
    --topbar: color-mix(in srgb, var(--surface) 92%, transparent);

    --text-inverse: #ffffff;

    --shadow-soft: 0 16px 38px rgba(13, 23, 40, 0.075);
    --shadow-card: 0 8px 24px rgba(13, 23, 40, 0.055);
    --shadow-hover: 0 18px 42px rgba(13, 23, 40, 0.105);
    --bg-main: var(--bg);
    --bg-card: var(--surface);
    --text-main: var(--text-primary);
    --navy: var(--sidebar);
    --navy-2: color-mix(in srgb, var(--sidebar) 84%, var(--accent));
    --gold: var(--accent);
    --green: var(--success);
    --blue: var(--info);
    --orange: var(--warning);
    --red: var(--danger);
}

html,
body,
button,
input,
select,
textarea,
.dropdown-menu,
.form-control,
.form-select {
    font-family: var(--font-sans) !important;
}

body {


    line-height: var(--line-body);
