/* Canonical KPI / Stat Card Conversion */
.app-stat-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: var(--card-gap, 12px) !important;
    margin: var(--section-gap, 14px) 0 !important;
}

.app-stat-card {
    position: relative;

    align-items: flex-start;

    min-height: var(--kpi-card-min-height, 108px) !important;
    padding: var(--card-padding, 16px) !important;
    border: 1px solid var(--border-soft) !important;
    border-radius: var(--radius-card, 18px) !important;
    background: var(--surface) !important;
    color: var(--text-primary) !important;
    box-shadow: var(--shadow-card) !important;

}

.app-stat-card::after {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 82%, transparent), transparent 72%);
    opacity: .76;
    pointer-events: none;
}

.app-stat-card > div:last-child,
.app-stat-card .stat-content,
.dashboard-stat-card > div:last-child {
    min-width: 0;
    flex: 1 1 auto;
}

.app-stat-card p:first-child,
.app-stat-card span:first-child:not(.badge):not(.app-stat-helper):not(.status-badge) {
    display: block;
    margin: 0 0 6px !important;
    color: var(--text-muted) !important;
    font-size: var(--text-sm) !important;
    font-weight: var(--font-weight-strong) !important;
    letter-spacing: var(--letter-label) !important;
    text-transform: uppercase;
    line-height: 1.25;
}

.app-stat-card h3,
.app-stat-card strong:not(.badge) {
    display: block;
    margin: 0 !important;
    color: var(--text-primary) !important;
    font-family: var(--font-number) !important;
    font-size: var(--text-kpi-number) !important;
    font-weight: var(--font-weight-number) !important;
    font-feature-settings: "tnum" 1, "lnum" 1;
    font-variant-numeric: tabular-nums lining-nums;
    letter-spacing: -0.025em;
    line-height: var(--line-tight) !important;
}

.app-stat-card .app-stat-helper,
.app-stat-card .small-muted,
.app-stat-card small,
.app-stat-helper {
    display: block;
    margin-top: 5px !important;
    color: var(--text-muted) !important;
    font-size: var(--text-sm) !important;
    line-height: 1.35;
    font-weight: 500;
}

.app-stat-icon {
    width: 42px !important;
    height: 42px !important;
    min-width: 42px !important;
    border-radius: 13px !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--primary) !important;
    background: color-mix(in srgb, var(--accent) 14%, var(--surface)) !important;
    border: 1px solid color-mix(in srgb, var(--accent) 18%, transparent) !important;
}

.stat-info { color: var(--info) !important; background: color-mix(in srgb, var(--info) 12%, var(--surface)) !important; }
.stat-success { color: var(--success) !important; background: color-mix(in srgb, var(--success) 12%, var(--surface)) !important; }
.stat-warning { color: var(--warning) !important; background: color-mix(in srgb, var(--warning) 12%, var(--surface)) !important; }
.stat-danger { color: var(--danger) !important; background: color-mix(in srgb, var(--danger) 12%, var(--surface)) !important; }

/* KPI tone classes for role landing dashboards — must come after .app-stat-icon reset */
.app-stat-icon.kpi-blue,
.kpi-icon.kpi-blue,
.kpi-blue { color: var(--info) !important; background: color-mix(in srgb, var(--info) 12%, var(--surface)) !important; border-color: color-mix(in srgb, var(--info) 18%, transparent) !important; }
.app-stat-icon.kpi-green,
.kpi-icon.kpi-green,
.kpi-green { color: var(--success) !important; background: color-mix(in srgb, var(--success) 12%, var(--surface)) !important; border-color: color-mix(in srgb, var(--success) 18%, transparent) !important; }
.app-stat-icon.kpi-orange,
.kpi-icon.kpi-orange,
.kpi-orange { color: var(--warning) !important; background: color-mix(in srgb, var(--warning) 12%, var(--surface)) !important; border-color: color-mix(in srgb, var(--warning) 18%, transparent) !important; }
.app-stat-icon.kpi-red,
.kpi-icon.kpi-red,
.kpi-red { color: var(--danger) !important; background: color-mix(in srgb, var(--danger) 12%, var(--surface)) !important; border-color: color-mix(in srgb, var(--danger) 18%, transparent) !important; }

/* Dark-mono boost for kpi-* icon visibility */
[data-theme="dark-mono"] .app-stat-icon.kpi-blue,
[data-theme="dark-mono"] .kpi-blue { color: #93c5fd !important; background: rgba(59, 130, 246, .18) !important; border-color: rgba(59, 130, 246, .28) !important; }
[data-theme="dark-mono"] .app-stat-icon.kpi-green,
[data-theme="dark-mono"] .kpi-green { color: #86efac !important; background: rgba(34, 197, 94, .18) !important; border-color: rgba(34, 197, 94, .28) !important; }
[data-theme="dark-mono"] .app-stat-icon.kpi-orange,
[data-theme="dark-mono"] .kpi-orange { color: #fcd34d !important; background: rgba(245, 158, 11, .18) !important; border-color: rgba(245, 158, 11, .28) !important; }
[data-theme="dark-mono"] .app-stat-icon.kpi-red,
[data-theme="dark-mono"] .kpi-red { color: #fca5a5 !important; background: rgba(239, 68, 68, .18) !important; border-color: rgba(239, 68, 68, .28) !important; }

.app-stat-card.success::after { background: linear-gradient(90deg, var(--success), transparent 72%); }
.app-stat-card.warning::after { background: linear-gradient(90deg, var(--warning), transparent 72%); }
.app-stat-card.danger::after { background: linear-gradient(90deg, var(--danger), transparent 72%); }
.app-stat-card.info::after { background: linear-gradient(90deg, var(--info), transparent 72%); }

.dashboard-stat-grid {
    gap: var(--card-gap, 12px) !important;
}

.dashboard-stat-card {
    min-height: var(--kpi-card-min-height, 108px) !important;
}

.print-app-stat-grid .app-stat-card.print-box,
.app-stat-card.print-box {
    display: block;
    min-height: auto !important;
