/* ==================================================
   Motion and micro-interaction system
   ================================================== */
:root {
    --motion-fast: 120ms;
    --motion-normal: 180ms;
    --motion-slow: 240ms;
    --motion-ease: cubic-bezier(.2, .8, .2, 1);
    --transition-fast: var(--motion-fast) var(--motion-ease);
    --transition: var(--motion-normal) var(--motion-ease);
    --transition-normal: var(--motion-normal) var(--motion-ease);
    --transition-slow: var(--motion-slow) var(--motion-ease);
}

html {
    scroll-behavior: smooth;
}

body {
    -webkit-tap-highlight-color: transparent;
}

@keyframes appPageEnter {
    from {
        opacity: 0;
        transform: translate3d(0, 8px, 0);
    }
    to {
        opacity: 1;
        transform: translate3d(0, 0, 0);
    }
}

@keyframes appCardEnter {
    from {
        opacity: 0;
        transform: translate3d(0, 10px, 0) scale(.992);
    }
    to {
        opacity: 1;
        transform: translate3d(0, 0, 0) scale(1);
    }
}

@keyframes appSkeletonShimmer {
    from {
        background-position: 120% 0;
    }
    to {
        background-position: -120% 0;
    }
}

.ui-motion-ready .app-main,
.ui-motion-ready .auth-wrapper {
    animation: appPageEnter var(--motion-slow) var(--motion-ease) both;
}

[data-motion-ready="true"] .motion-watch:not(.is-motion-visible) {
    opacity: 0;
    transform: translate3d(0, 10px, 0) scale(.992);
}

.motion-watch.is-motion-visible {
    animation: appCardEnter var(--motion-slow) var(--motion-ease) both;
    animation-delay: calc(min(var(--motion-index, 0), 8) * 18ms);
}

.app-card,
.app-stat-card,
.dashboard-chart-card,
.dashboard-summary-card,
.dashboard-table-card,
.table-responsive,
.form-section,
.filter-card,
.empty-state,
.auth-card {
    transition:
        border-color var(--motion-normal) var(--motion-ease),
        background-color var(--motion-normal) var(--motion-ease),
        box-shadow var(--motion-normal) var(--motion-ease),
        transform var(--motion-normal) var(--motion-ease),
        opacity var(--motion-normal) var(--motion-ease);
}

.app-card:hover,
.app-stat-card:hover,
.dashboard-chart-card:hover,
.dashboard-summary-card:hover,
.dashboard-table-card:hover {
    transform: translate3d(0, -1px, 0);
    box-shadow: var(--shadow-card);
}

.app-btn,
.btn,
button,
.dropdown-item,
.sidebar-link,
.sidebar-group-toggle,
.theme-mode-option,
.dashboard-checkbox-chip,
.page-link {
    transition:
        color var(--motion-fast) var(--motion-ease),
        background-color var(--motion-fast) var(--motion-ease),
        border-color var(--motion-fast) var(--motion-ease),
        box-shadow var(--motion-fast) var(--motion-ease),
        transform var(--motion-fast) var(--motion-ease),
        opacity var(--motion-fast) var(--motion-ease);
}

.app-btn:hover,
.btn:hover,
.theme-mode-option:hover,
.page-link:hover,
.dashboard-checkbox-chip:hover {
    transform: translate3d(0, -1px, 0);
}

.app-btn:active,
.btn:active,
button:active,
.sidebar-link:active,
.sidebar-group-toggle:active,
.theme-mode-option:active,
.page-link:active,
.dropdown-item:active,
.is-pressing {
    transform: translate3d(0, 0, 0) scale(.985);
}

.sidebar-link:hover,
.sidebar-group-toggle:hover,
.dropdown-item:hover,
.dropdown-item:focus {
    transform: translate3d(2px, 0, 0);
}

.sidebar-chevron,
.dropdown-toggle::after {
    transition: transform var(--motion-normal) var(--motion-ease), opacity var(--motion-fast) var(--motion-ease);
}

.sidebar-group[open] .sidebar-submenu {
    animation: appCardEnter var(--motion-normal) var(--motion-ease) both;
    transform-origin: top center;
}

.sidebar-submenu {
    transition: opacity var(--motion-normal) var(--motion-ease), transform var(--motion-normal) var(--motion-ease);
}

.dropdown-menu {
    transition: opacity var(--motion-fast) var(--motion-ease), transform var(--motion-fast) var(--motion-ease), visibility var(--motion-fast) var(--motion-ease);
    transform-origin: top right;
}

.dropdown-menu:not(.show) {
    opacity: 0;
    transform: translate3d(0, 6px, 0) scale(.985);
    pointer-events: none;
}

.dropdown-menu.show {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
}

.modal.fade .modal-dialog {
    transition: transform var(--motion-slow) var(--motion-ease), opacity var(--motion-slow) var(--motion-ease);
    transform: translate3d(0, 12px, 0) scale(.985);
}

.modal.show .modal-dialog {
    transform: translate3d(0, 0, 0) scale(1);
}

.offcanvas,
.app-sidebar,
.sidebar-backdrop {
    transition: transform var(--motion-slow) var(--motion-ease), opacity var(--motion-slow) var(--motion-ease), visibility var(--motion-slow) var(--motion-ease);
}

.form-control,
.form-select,
.form-check-input,
textarea,
select,
input {
    transition:
        border-color var(--motion-fast) var(--motion-ease),
        box-shadow var(--motion-fast) var(--motion-ease),
        background-color var(--motion-fast) var(--motion-ease),
        color var(--motion-fast) var(--motion-ease);
}

.form-control:focus,
.form-select:focus,
.form-check-input:focus,
textarea:focus,
select:focus,
input:focus {
    transform: none;
}

.table tbody tr,
.app-table tbody tr,
.table-hover tbody tr {
    transition: background-color var(--motion-fast) var(--motion-ease), box-shadow var(--motion-fast) var(--motion-ease), transform var(--motion-fast) var(--motion-ease);
}

.table tbody tr:hover,
.app-table tbody tr:hover,
.table-hover tbody tr:hover {
    transform: translate3d(0, -1px, 0);
}

.badge,
.status-badge,
.alert,
.toast {
    transition:
        color var(--motion-fast) var(--motion-ease),
        background-color var(--motion-fast) var(--motion-ease),
        border-color var(--motion-fast) var(--motion-ease),
        opacity var(--motion-fast) var(--motion-ease),
        transform var(--motion-fast) var(--motion-ease);
}

.alert.show,
.toast.show {
    transform: translate3d(0, -1px, 0);
}

[data-ui-action="drilldown"],
[data-preserve-scroll],
[data-tab-target],
.nav-tabs .nav-link,
.nav-pills .nav-link {
    transition:
        color var(--motion-fast) var(--motion-ease),
        background-color var(--motion-fast) var(--motion-ease),
        border-color var(--motion-fast) var(--motion-ease),
        transform var(--motion-fast) var(--motion-ease),
        box-shadow var(--motion-fast) var(--motion-ease);
}

[data-ui-action="drilldown"]:hover,
[data-preserve-scroll]:hover,
[data-tab-target]:hover,
.nav-tabs .nav-link:hover,
.nav-pills .nav-link:hover {
    transform: translate3d(0, -1px, 0);
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation: none !important;
        transition: none !important;
        scroll-behavior: auto !important;
    }

    html {
        scroll-behavior: auto !important;
    }

    [data-motion-ready="true"] .motion-watch:not(.is-motion-visible),
