/* ==================================================
   PRODUCTION — SDM/HR Enterprise Redesign
   Scope: HR dashboard, employees, payrolls, payroll detail, generate, payment history.
   No DB migration; visual/component layer only.
   ================================================== */
.hr-enterprise-page .page-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 6px;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.hr-kpi-grid.app-stat-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: var(--card-gap);
}

.hr-enterprise-grid {
    display: grid;
    gap: var(--section-gap);
}

.hr-enterprise-grid.two-col {
    grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
}

.hr-section-title {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
}

.hr-section-title span:first-child {
    display: block;
    margin-bottom: 4px;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.075em;
    text-transform: uppercase;
}

.hr-section-title h2 {
    margin: 0;
    color: var(--text-primary);
    font-size: 18px;
    font-weight: 700;
    letter-spacing: -0.025em;
}

.hr-table-count {
    display: inline-flex;
    align-items: center;
    min-height: 30px;
    padding: 6px 10px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-badge);
    background: var(--surface-soft);
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}

.hr-lifecycle-list {
    display: grid;
    gap: 10px;
}

.hr-lifecycle-list.compact {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.hr-lifecycle-list.detail {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.hr-lifecycle-step {
    position: relative;
    display: grid;
    gap: 4px;
    min-height: 104px;
    padding: 14px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-card);
    background: var(--surface-soft);
    color: var(--text-secondary);
}

.hr-lifecycle-step::before {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    border-radius: var(--radius-card) 0 0 var(--radius-card);
    background: var(--border-soft);
}

.hr-lifecycle-step strong {
    color: var(--text-primary);
    font-size: 13px;
    font-weight: 700;
}

.hr-lifecycle-step span {
    color: var(--text-secondary);
    font-size: 13px;
    font-weight: 700;
}

.hr-lifecycle-step small {
    color: var(--text-muted);
    line-height: 1.35;
}

.hr-lifecycle-step.is-active,
.hr-lifecycle-step.is-complete,
.hr-lifecycle-step.is-warning {
    background: var(--surface);
}

.hr-lifecycle-step.is-active::before { background: var(--primary); }
.hr-lifecycle-step.is-complete::before { background: var(--success); }
.hr-lifecycle-step.is-warning::before { background: var(--warning); }
.hr-lifecycle-step.is-pending::before { background: var(--border-soft); }

.hr-health-list {
    display: grid;
    gap: 10px;
}

.hr-health-item {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr);
    gap: 12px;
    align-items: center;
    padding: 12px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-card);
    background: var(--surface-soft);
}

.hr-health-item i {
    width: 42px;
    height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-badge);
    background: var(--surface-muted);
    color: var(--primary);
    font-size: 18px;
}

.hr-health-item strong {
    display: block;
    color: var(--text-primary);
    font-size: 18px;
    font-weight: 700;
    line-height: 1.1;
}

.hr-health-item span {
    color: var(--text-muted);
    font-size: 12px;
}

.hr-health-item.is-ok i { color: var(--success); background: var(--success-soft); }
.hr-health-item.is-warning i { color: var(--warning); background: var(--warning-soft); }
.hr-health-item.is-muted i { color: var(--text-muted); }

.hr-status-badge,
.hr-posting-badge,
.hr-soft-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: 26px;
    padding: 4px 9px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-badge);
    background: var(--surface-soft);
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}

.hr-status-badge.is-active,
.hr-status-badge.is-paid,
.hr-posting-badge.is-success {
    border-color: color-mix(in srgb, var(--success) 36%, var(--border-soft));
    background: var(--success-soft);
    color: var(--success);
}

.hr-status-badge.is-draft,
.hr-posting-badge.is-muted,
.hr-status-badge.is-inactive {
    border-color: var(--border-soft);
    background: var(--surface-muted);
    color: var(--text-muted);
}

.hr-status-badge.is-final,
.hr-status-badge.is-posted,
.hr-posting-badge.is-warning {
    border-color: color-mix(in srgb, var(--warning) 36%, var(--border-soft));
    background: var(--warning-soft);
    color: var(--warning);
}

.hr-posting-badge.is-danger {
    border-color: color-mix(in srgb, var(--danger) 36%, var(--border-soft));
    background: var(--danger-soft);
    color: var(--danger);
}

.hr-badge-wrap {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.hr-filter-form.app-filter-form {
    display: grid;
    grid-template-columns: repeat(3, minmax(150px, 1fr)) auto;
    gap: 12px;
    align-items: end;
}

.hr-filter-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
}

.hr-form-grid {
    display: grid;
    gap: 14px;
}

.hr-form-grid.two-col {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.hr-inline-status {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    padding: 12px 14px;
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-card);
    background: var(--surface-soft);
    color: var(--text-secondary);
    font-size: 13px;
    line-height: 1.45;
}

.hr-inline-status i {
    margin-top: 1px;
    color: var(--primary);
}

.hr-inline-status.is-info {
    border-color: color-mix(in srgb, var(--info) 34%, var(--border-soft));
    background: var(--info-soft);
}

.hr-inline-status.is-muted {
    background: var(--surface-muted);
}

.hr-payroll-payment-form,
.hr-payroll-generate-form,
.hr-employee-form {
    display: grid;
    gap: 16px;
}

.hr-payroll-detail-table input[readonly] {
    background: var(--surface-muted) !important;
    color: var(--text-muted) !important;
}

.hr-empty-state.app-empty-state,
.hr-empty-state.empty-state {
    min-height: auto;
    padding-block: 28px !important;
}

.hr-total-payroll-card {
    grid-column: span 2;
}

.hr-master-settings-page-shell .app-stat-card p {
    margin: 0 0 4px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 700;
}

.hr-master-settings-page-shell .app-stat-card h3 {
    margin: 0;
    color: var(--text-primary);
    font-size: clamp(20px, 2vw, 28px);
    font-weight: 700;
    letter-spacing: -0.035em;
}

.hr-master-settings-page-shell .app-stat-helper {
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.35;
}

@media (max-width: 1199.98px) {
    .hr-enterprise-grid.two-col,
    .hr-lifecycle-list.compact,
    .hr-lifecycle-list.detail {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .hr-filter-form.app-filter-form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 767.98px) {
    .hr-enterprise-grid.two-col,
    .hr-lifecycle-list.compact,
    .hr-lifecycle-list.detail,
    .hr-form-grid.two-col,
    .hr-filter-form.app-filter-form {
        grid-template-columns: 1fr;
    }

    .hr-section-title {
        display: grid;
    }

    .hr-table-count,
    .hr-filter-actions,
    .hr-filter-actions .btn,
    .hr-total-payroll-card {
        width: 100%;
        grid-column: auto;
    }

    .hr-filter-actions {
        justify-content: stretch;
    }

    .hr-lifecycle-step {
        min-height: auto;
    }
}
.stat-muted { color: var(--text-muted) !important; background: var(--surface-muted) !important; }


/* ==================================================
   PRODUCTION SOP Center Per Role
   ================================================== */
.sop-page {
    display: flex;
    flex-direction: column;
    gap: var(--space-5, 1.25rem);
}

.sop-summary-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.sop-hero-card .card-body,
.sop-document > .card-body {
    padding: clamp(1rem, 2vw, 1.5rem);
}

.sop-hero-content {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 1.25rem;
    align-items: center;
}

.sop-mini-label {
    display: inline-flex;
    align-items: center;
    gap: .35rem;
    margin-bottom: .35rem;
    font-size: .72rem;
    font-weight: 700;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--text-muted);
}

.sop-hero-content h2,
.sop-document-header h2,
.sop-role-card h2 {
    margin: 0;
    color: var(--text-strong);
    font-weight: 700;
}

.sop-hero-content p,
.sop-document-header p,
.sop-role-card p {
    margin: .45rem 0 0;
    color: var(--text-muted);
    line-height: 1.6;
}

.sop-hero-badge {
    min-width: 180px;
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-xl, 1rem);
    padding: 1rem;
    background: var(--surface-soft);
    display: flex;
    flex-direction: column;
    gap: .25rem;
    color: var(--text-strong);
}

.sop-hero-badge i {
    font-size: 1.6rem;
    color: var(--success-color, #16a34a);
}

.sop-hero-badge span {
    color: var(--text-muted);
    font-size: .86rem;
}

.sop-role-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--space-4, 1rem);
}

.sop-role-card {
    text-decoration: none;
    color: inherit;
    transition: transform .16s ease, border-color .16s ease, box-shadow .16s ease;
}

.sop-role-card:hover {
    transform: translateY(-2px);
    border-color: var(--primary-border, rgba(59, 130, 246, .35));
    box-shadow: var(--shadow-md, 0 12px 30px rgba(15, 23, 42, .12));
}

.sop-role-card-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: .85rem;
}

.sop-role-icon,
.sop-document-icon {
    width: 42px;
    height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: var(--surface-soft);
    border: 1px solid var(--border-subtle);
    color: var(--accent-strong, var(--bs-primary));
    font-size: 1.2rem;
}

.sop-card-link {
    display: inline-flex;
    margin-top: 1rem;
    font-weight: 700;
    color: var(--accent-strong, var(--bs-primary));
}

.sop-detail-layout {
    display: grid;
    grid-template-columns: 280px minmax(0, 1fr);
    gap: var(--space-5, 1.25rem);
    align-items: start;
}

.sop-detail-side {
    position: sticky;
    top: 1rem;
}

.sop-nav-title {
    display: flex;
    align-items: center;
    gap: .5rem;
    font-weight: 700;
    color: var(--text-strong);
    margin-bottom: .8rem;
}

.sop-nav-list {
    display: flex;
    flex-direction: column;
    gap: .35rem;
}

.sop-nav-link {
    display: flex;
    align-items: center;
    gap: .55rem;
    min-height: 40px;
    padding: .55rem .65rem;
    border-radius: .85rem;
    text-decoration: none;
    color: var(--text-muted);
    font-weight: 700;
}

.sop-nav-link:hover,
.sop-nav-link.active {
    color: var(--text-strong);
    background: var(--surface-soft);
}

.sop-document-header {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
    padding-bottom: 1.1rem;
    border-bottom: 1px solid var(--border-subtle);
    margin-bottom: 1rem;
}

.sop-section {
    padding: 1rem 0;
    border-bottom: 1px solid var(--border-subtle);
}

.sop-section:last-child {
    border-bottom: 0;
    padding-bottom: 0;
}

.sop-section h3 {
    display: flex;
    align-items: center;
    gap: .55rem;
    margin: 0 0 .75rem;
    font-size: 1.02rem;
    font-weight: 700;
    color: var(--text-strong);
}

.sop-check-list,
.sop-step-list {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: .55rem;
}

.sop-check-list li {
    position: relative;
    padding-left: 1.35rem;
    color: var(--text-body, var(--text-muted));
    line-height: 1.58;
}

.sop-check-list li::before {
    content: "";
    position: absolute;
    left: 0;
    top: .58rem;
    width: .45rem;
    height: .45rem;
    border-radius: 999px;
    background: var(--accent-strong, var(--bs-primary));
}

.sop-step-list li {
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr);
    gap: .7rem;
    align-items: start;
}

.sop-step-list li > span {
    width: 34px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: var(--surface-soft);
    border: 1px solid var(--border-subtle);
    color: var(--text-strong);
    font-weight: 700;
}

.sop-step-list p {
    margin: .25rem 0 0;
    color: var(--text-body, var(--text-muted));
    line-height: 1.58;
}

.sop-journal-section h3 i {
    color: var(--success-color, #16a34a);
}

.sop-warning-section h3 i {
    color: var(--warning-color, #d97706);
}

.sop-danger-section h3 i {
    color: var(--danger-color, #dc2626);
}

.sop-work-link-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: .65rem;
}

.sop-work-link {
    min-height: 48px;
    display: flex;
    align-items: center;
    gap: .65rem;
    padding: .7rem .8rem;
    border: 1px solid var(--border-subtle);
    border-radius: .9rem;
    background: var(--surface-soft);
    color: var(--text-strong);
    text-decoration: none;
    font-weight: 700;
}

.sop-work-link:hover {
    border-color: var(--primary-border, rgba(59, 130, 246, .35));
}

.sop-work-link.disabled {
    opacity: .55;
    pointer-events: none;
}

.sop-print-links {
    display: none;
}

@media (max-width: 1199.98px) {
