/* ==================================================
   PRODUCTION — Omzet & Revenue Explorer + Empty Chart Cleanup
   Read-only dashboard revenue analytics. No DB mutation.
   ================================================== */
.revenue-explorer-section {
    display: flex;
    flex-direction: column;
    gap: var(--space-4, 1rem);
}

.revenue-explorer-header {
    align-items: flex-start;
}

.revenue-explorer-filter {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));

    align-items: end;

    border: 1px solid var(--app-border, rgba(148, 163, 184, .24));
    border-radius: var(--radius-xl, 18px);
    background: var(--app-card-bg, rgba(255, 255, 255, .78));
    box-shadow: var(--app-shadow-sm, 0 10px 28px rgba(15, 23, 42, .08));
}

.revenue-explorer-stat-grid {
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.revenue-explorer-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(300px, .85fr);
    gap: var(--space-4, 1rem);
    align-items: stretch;
}

.revenue-trend-card,
.revenue-mix-card {
    padding: var(--space-5, 1.25rem);
}

.revenue-trend-chart {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(72px, 1fr);
    gap: var(--space-3, .75rem);
    min-height: 260px;
    overflow-x: auto;
    padding: var(--space-4, 1rem) var(--space-2, .5rem) var(--space-2, .5rem);
    border: 1px solid var(--app-border-soft, rgba(148, 163, 184, .16));
    border-radius: var(--radius-lg, 16px);
    background: linear-gradient(180deg, var(--app-surface-muted, rgba(248, 250, 252, .76)), transparent);
}

.revenue-trend-group {
    display: grid;
    grid-template-rows: 1fr auto auto;
    align-items: end;
    min-width: 72px;
    gap: .45rem;
}

.revenue-trend-bars {
    display: flex;
    align-items: end;
    justify-content: center;
    gap: .32rem;
    height: 170px;
    padding-inline: .25rem;
}

.revenue-bar {
    display: inline-block;
    width: 14px;
    min-height: 5px;
    height: max(5px, var(--bar-height, 0%));
    border-radius: 999px 999px 6px 6px;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .25);
}

.revenue-bar-selected,
.revenue-legend-selected,
.revenue-mix-invoice .dashboard-legend-dot {
    background: var(--app-primary, #2563eb);
}

.revenue-bar-cash,
.revenue-legend-cash,
.revenue-mix-canteen_paid .dashboard-legend-dot {
    background: var(--app-success, #16a34a);
}

.revenue-bar-invoice,
.revenue-legend-invoice,
.revenue-mix-canteen_debt .dashboard-legend-dot {
    background: var(--app-warning, #f59e0b);
}

.revenue-trend-label {
    font-size: .78rem;
    font-weight: 700;
    color: var(--app-text, #0f172a);
    text-align: center;
    white-space: nowrap;
}

.revenue-trend-group small {
    display: block;
    font-size: .68rem;
    color: var(--app-muted, #64748b);
    text-align: center;
    white-space: nowrap;
}

.revenue-mix-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-4, 1rem);
}

.revenue-mix-donut {
    width: min(220px, 100%);
    aspect-ratio: 1 / 1;
    margin: 0 auto;
    border-radius: 999px;
    display: grid;
    place-items: center;
    background:
        radial-gradient(circle at center, var(--app-card-bg, #fff) 0 48%, transparent 49%),
        conic-gradient(
            var(--app-primary, #2563eb) 0 var(--mix-a, 0%),
            var(--app-success, #16a34a) var(--mix-a, 0%) var(--mix-b, 0%),
            var(--app-warning, #f59e0b) var(--mix-b, 0%) 100%
        );
    box-shadow: var(--app-shadow-sm, 0 14px 34px rgba(15, 23, 42, .10));
}

.revenue-mix-donut span {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: .15rem;
    width: 48%;
    aspect-ratio: 1 / 1;
    border-radius: 999px;
    background: var(--app-card-bg, rgba(255, 255, 255, .86));
    text-align: center;
}

.revenue-mix-donut strong {
    font-size: 1.2rem;
    line-height: 1;
}

.revenue-mix-donut small {
    font-size: .72rem;
    color: var(--app-muted, #64748b);
}

.revenue-mix-list {
    display: grid;
    gap: var(--space-2, .5rem);
}

.revenue-mix-item {
    display: grid;
    gap: .2rem;
    padding: .85rem .95rem;
    border: 1px solid var(--app-border-soft, rgba(148, 163, 184, .16));
    border-radius: var(--radius-lg, 16px);
    color: inherit;
    text-decoration: none;
    background: var(--app-surface-muted, rgba(248, 250, 252, .68));
}

.revenue-mix-item:hover {
    transform: translateY(-1px);
    box-shadow: var(--app-shadow-sm, 0 10px 26px rgba(15, 23, 42, .10));
}

.revenue-mix-item span {
    display: flex;
    align-items: center;
    gap: .45rem;
    font-weight: 700;
}

.revenue-mix-item strong {
    font-size: 1rem;
}

.revenue-mix-item small {
    color: var(--app-muted, #64748b);
}

.revenue-explorer-note-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: var(--space-3, .75rem);
}

.revenue-explorer-note {
    display: flex;
    align-items: flex-start;
    gap: .55rem;
    padding: .85rem 1rem;
    border: 1px solid var(--app-border-soft, rgba(148, 163, 184, .18));
    border-radius: var(--radius-lg, 16px);
    background: var(--app-surface-muted, rgba(248, 250, 252, .70));
    color: var(--app-muted, #64748b);
    font-size: .86rem;
}

.revenue-explorer-empty {
    min-height: unset;
}

@media (max-width: 992px) {
    .revenue-explorer-grid {
        grid-template-columns: 1fr;
    }

    .revenue-trend-chart {
        grid-auto-columns: minmax(68px, 82px);
    }
}

@media (max-width: 576px) {
    .revenue-explorer-filter {
        grid-template-columns: 1fr;
    }

    .revenue-explorer-header .page-actions,
    .revenue-explorer-header .page-actions .btn,
    .revenue-explorer-filter .btn {
        width: 100%;
    }

    .revenue-trend-card,
