/* ==================================================
   PRODUCTION SOURCE: 100_theme_black_white_lock.css
   Black/White Theme Lock.
   Final active theme contract: Dark Mono and Light Mono only.
   Legacy themes are migrated by base template + main.js and no longer appear
   as selectable UI modes.
   ================================================== */

:root,
[data-theme="light-mono"] {
    color-scheme: light;
    --font-sans: "Inter", "Manrope", "Plus Jakarta Sans", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    --font-number: "Inter", "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

    --topbar: rgba(255, 255, 255, 0.94);

    --text-inverse: #ffffff;
    --accent: #000000;
    --primary: #000000;
    --primary-hover: #262626;
    --primary-text: #ffffff;
    --secondary: #ffffff;
    --secondary-hover: #f5f5f5;
    --secondary-text: #111111;

    --success: #15803d;
    --success-soft: #dcfce7;
    --warning: #b45309;
    --warning-soft: #fef3c7;
    --danger: #b91c1c;
    --danger-soft: #fee2e2;
    --info: #1d4ed8;
    --info-soft: #dbeafe;

    --shadow-hover: 0 16px 36px rgba(0, 0, 0, 0.10);

    --bg-main: var(--bg);
    --bg-card: var(--surface);
    --text-main: var(--text-primary);
    --navy: var(--sidebar);
    --navy-2: #171717;
    --gold: var(--accent);
    --green: var(--success);
    --blue: var(--info);
    --orange: var(--warning);
    --red: var(--danger);
}

[data-theme="dark-mono"] {
    color-scheme: dark;
    --font-sans: "Inter", "Manrope", "Plus Jakarta Sans", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    --font-number: "Inter", "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

    --topbar: rgba(5, 5, 5, 0.94);

    --text-inverse: #050505;
    --accent: #ffffff;
    --primary: #ffffff;
    --primary-hover: #e5e5e5;
    --primary-text: #050505;
    --secondary: #171717;
    --secondary-hover: #262626;
    --secondary-text: #f5f5f5;

    --success: #22c55e;
    --success-soft: rgba(34, 197, 94, 0.16);
    --warning: #f59e0b;
    --warning-soft: rgba(245, 158, 11, 0.16);
    --danger: #ef4444;
    --danger-soft: rgba(239, 68, 68, 0.16);
    --info: #60a5fa;
    --info-soft: rgba(96, 165, 250, 0.16);

    --shadow-hover: 0 16px 38px rgba(0, 0, 0, 0.42);

    --bg-main: var(--bg);
    --bg-card: var(--surface);
    --text-main: var(--text-primary);
    --navy: var(--sidebar);
    --navy-2: #0d0d0d;
    --gold: var(--accent);
    --green: var(--success);
    --blue: var(--info);
    --orange: var(--warning);
    --red: var(--danger);
}

.app-main {
    background: var(--bg);
    color: var(--text-primary);
}

.app-topbar,
.auth-card,
.app-card,
.content-card,
.card,
.kpi-card,
.dashboard-panel,
.placeholder-panel,
.master-menu-card,
.logistics-process-panel,
.table-responsive,
.table-wrapper,
.app-table-wrap,
.app-table-wrapper,
.data-table-wrapper,
.empty-state,
.metric-card,
.dashboard-chart-card,
.dashboard-analytics-card,
.dashboard-donut-metric,
.dashboard-donut-status-card,
.dashboard-chart-empty,
.user-chip,
.topbar-icon-link,
.quick-item-btn,
.worker-result-item,
.custom-item-box,
.form-control,
.form-select,
.list-group-item,
.dropdown-menu,
.offcanvas,
.alert.app-alert,
.filter-card,
.page-header {
    background-color: var(--surface) !important;
    border-color: var(--border-soft) !important;
    color: var(--text-primary) !important;
    box-shadow: var(--shadow-card);
}

[data-theme="light-mono"] .app-main {
    background: #ffffff;
}

[data-theme="dark-mono"] .app-main {
    background: #050505;
}

[data-theme="dark-mono"] .app-topbar,
[data-theme="dark-mono"] .dropdown-menu,
[data-theme="dark-mono"] .offcanvas,
[data-theme="dark-mono"] .form-control,
[data-theme="dark-mono"] .form-select {
    background-color: #0d0d0d !important;
    color: #f5f5f5 !important;
}

.table thead th,
.app-table thead th {


    border-color: var(--border-soft) !important;
}

.btn-primary,
.app-btn-primary,
.dashboard-filter-submit {
    background: var(--primary) !important;
    border-color: var(--primary) !important;
    color: var(--primary-text) !important;
}

.btn-outline-secondary,
.btn-secondary,
.app-btn-secondary,
.app-btn-ghost {
    background: var(--secondary) !important;
    border-color: var(--border) !important;
    color: var(--secondary-text) !important;
}

.theme-mode-option[data-theme-option="dark-mono"].is-active::after,
.theme-mode-option[data-theme-option="light-mono"].is-active::after {
    color: var(--accent);
}

.status-success,
.text-success {
    color: var(--success) !important;
}

.status-warning,
.text-warning {
    color: var(--warning) !important;
}

.status-danger,
.text-danger {
    color: var(--danger) !important;
}

.status-info,
.text-info {
    color: var(--info) !important;
}

/* ==================================================
   Dark-Mono: Bootstrap Subtle Badge Readability Fix
   Problem: bg-*-subtle backgrounds are light cream/pastel,
   paired with text-* colors that are also light in dark mode.
   Fix: Override subtle backgrounds to use dark translucent tones,
   and ensure text color contrasts properly.
   ================================================== */
[data-theme="dark-mono"] .bg-warning-subtle,
[data-theme="dark-mono"] .badge.bg-warning-subtle {
    background-color: rgba(245, 158, 11, .16) !important;
    color: #fcd34d !important;
    border-color: rgba(245, 158, 11, .32) !important;
}

[data-theme="dark-mono"] .bg-danger-subtle,
[data-theme="dark-mono"] .badge.bg-danger-subtle {
    background-color: rgba(239, 68, 68, .16) !important;
    color: #fca5a5 !important;
    border-color: rgba(239, 68, 68, .32) !important;
}

[data-theme="dark-mono"] .bg-success-subtle,
[data-theme="dark-mono"] .badge.bg-success-subtle {
    background-color: rgba(34, 197, 94, .16) !important;
    color: #86efac !important;
    border-color: rgba(34, 197, 94, .32) !important;
}

[data-theme="dark-mono"] .bg-info-subtle,
[data-theme="dark-mono"] .badge.bg-info-subtle {
    background-color: rgba(96, 165, 250, .16) !important;
    color: #93c5fd !important;
    border-color: rgba(96, 165, 250, .32) !important;
}

[data-theme="dark-mono"] .bg-primary-subtle,
[data-theme="dark-mono"] .badge.bg-primary-subtle {
    background-color: rgba(255, 255, 255, .10) !important;
    color: #e5e5e5 !important;
    border-color: rgba(255, 255, 255, .20) !important;
}

[data-theme="dark-mono"] .bg-secondary-subtle,
[data-theme="dark-mono"] .badge.bg-secondary-subtle {
    background-color: rgba(255, 255, 255, .08) !important;
    color: #a3a3a3 !important;
    border-color: rgba(255, 255, 255, .14) !important;
}

/* Ensure text-* classes inside badges inherit the corrected color */
[data-theme="dark-mono"] .bg-warning-subtle.text-warning,
[data-theme="dark-mono"] .bg-warning-subtle .text-warning { color: #fcd34d !important; }
[data-theme="dark-mono"] .bg-danger-subtle.text-danger,
