/* ==================================================
   PRODUCTION SOURCE: 134_atomic_static_alert_empty_state_polish.css
   Tahap 10.23 — Atomic Static Alert, Info Panel & Empty State Polish
   Purpose:
   - Static Bootstrap alert/info/warning boxes must look like app-owned UI,
     not raw Bootstrap blocks.
   - Empty-state panels across modules get consistent hierarchy, spacing,
     icon treatment, and mobile-safe layout.
   - CSS-only fallback; JS only adds helper classes/roles.
   ================================================== */

/* App-owned static alerts. Flash alerts that are centered keep their own rules. */
.alert.app-static-alert,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
    gap: 12px;
    width: 100%;
    margin: 0 0 var(--section-gap, 16px) !important;
    padding: 15px 16px 15px 14px !important;
    border: 1px solid var(--border, rgba(15, 23, 42, 0.12)) !important;
    border-radius: 22px !important;
    background: var(--surface, #ffffff) !important;
    color: var(--text-primary, #111111) !important;
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.08) !important;
    overflow: hidden;
}

.alert.app-static-alert::before,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before {
    content: "i";
    display: inline-flex;
    grid-column: 1;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 13px;
    background: color-mix(in srgb, var(--blue, #2563eb) 13%, transparent);
    color: var(--blue, #2563eb);
    font-size: 14px;
    font-weight: 700;
    line-height: 1;
    margin-top: 1px;
}

.alert.app-static-alert::after,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 5px;
    background: var(--blue, #2563eb);
}

.alert.app-static-alert > *,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) > * {
    grid-column: 2;
    min-width: 0;
}

.alert.app-static-alert strong,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) strong {
    color: var(--text-primary, #111111) !important;
    font-weight: 700;
}

.alert.app-static-alert p:last-child,
.alert.app-static-alert ul:last-child,
.alert.app-static-alert ol:last-child,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) p:last-child,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) ul:last-child,
.alert:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast) ol:last-child {
    margin-bottom: 0 !important;
}

.alert.alert-success.app-static-alert::before,
.alert.alert-success:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before {
    content: "✓";
    background: color-mix(in srgb, var(--green, #198754) 15%, transparent);
    color: var(--green, #198754);
}

.alert.alert-success.app-static-alert::after,
.alert.alert-success:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after {
    background: var(--green, #198754);
}

.alert.alert-warning.app-static-alert::before,
.alert.alert-warning:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before {
    content: "!";
    background: color-mix(in srgb, var(--amber, #b45309) 15%, transparent);
    color: var(--amber, #b45309);
}

.alert.alert-warning.app-static-alert::after,
.alert.alert-warning:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after {
    background: var(--amber, #b45309);
}

.alert.alert-danger.app-static-alert::before,
.alert.alert-error.app-static-alert::before,
.alert.alert-danger:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before,
.alert.alert-error:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before {
    content: "!";
    background: color-mix(in srgb, var(--red, #dc2626) 14%, transparent);
    color: var(--red, #dc2626);
}

.alert.alert-danger.app-static-alert::after,
.alert.alert-error.app-static-alert::after,
.alert.alert-danger:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after,
.alert.alert-error:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after {
    background: var(--red, #dc2626);
}

.alert.alert-info.app-static-alert::before,
.alert.alert-primary.app-static-alert::before,
.alert.alert-secondary.app-static-alert::before,
.alert.alert-info:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before,
.alert.alert-primary:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before,
.alert.alert-secondary:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::before {
