.alert.alert-info.app-static-alert::after,
.alert.alert-primary.app-static-alert::after,
.alert.alert-secondary.app-static-alert::after,
.alert.alert-info:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after,
.alert.alert-primary:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after,
.alert.alert-secondary:not(.app-alert):not(.app-flash-centered):not(.app-atomic-toast)::after {
