/* Empty states: normalize old and new variants without editing 100+ templates. */
.empty-state,
.app-empty-state,
.dashboard-empty-state,
.dashboard-chart-empty,
[data-empty-state="true"],
[data-ui-empty-state] {
    display: grid;
    justify-items: center;
    align-content: center;
    gap: 10px;
    width: 100%;
