/* UI polish v11: EOF authority layer.
   This block intentionally sits last so legacy dark/mobile rules cannot win. */
:root,
html[data-theme],
html[data-theme="light-mono"],
html[data-theme="dark-mono"] {
    --ui-final-orange: #F97316;
    --ui-final-orange-2: #FB923C;
    --ui-final-amber: #FBBF24;
    --ui-final-cream: #FEFBEE;
    --ui-final-cream-2: #FFF7ED;
    --ui-final-white: #FFFFFF;
    --ui-final-ink: #111827;
    --ui-final-muted: rgba(17, 24, 39, .62);
    --ui-final-soft: rgba(17, 24, 39, .42);
    --ui-final-line: rgba(249, 115, 22, .22);
    --ui-final-line-strong: rgba(249, 115, 22, .38);
    --ui-final-shadow: 0 14px 34px rgba(17, 24, 39, .075);
    --ui-final-shadow-soft: 0 8px 22px rgba(17, 24, 39, .05);

    --primary-text: var(--ui-final-white) !important;

    --success: var(--ui-final-orange) !important;
    --info: var(--ui-final-orange) !important;
    --warning: var(--ui-final-amber) !important;
    --danger: var(--ui-final-orange) !important;

}

html,
body,
body.is-public,
body.is-authenticated,
.auth-page,
.app-main,
.content-area,
.public-landing {
    color: var(--ui-final-ink) !important;
    background: linear-gradient(180deg, var(--ui-final-white) 0%, var(--ui-final-cream) 100%) !important;
}

:where(p, small, label, .text-muted, .page-description, .form-text, .topbar-subtitle, .brand-subtitle, .portal-web-subtitle) {
    color: var(--ui-final-muted) !important;
}

.auth-card {

    color: var(--ui-final-ink) !important;

}

a,
a:hover {
    color: var(--ui-final-orange) !important;
}

.portal-order-policy-strip,
.portal-admin-gate-grid,
.portal-draft-gate-grid,
.portal-draft-proof-form {
    display: grid;
    gap: 12px;
}

.portal-order-policy-strip {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin: 16px 0;
}

.portal-order-policy-strip article,
.portal-admin-gate-card {
    background: var(--surface-card, #fff);
    border: 1px solid var(--border-color, #d8dde6);
    border-radius: 18px;
    padding: 14px 16px;
}

.portal-order-policy-strip span,
.portal-admin-gate-card span {
    color: var(--text-muted, #64748b);
    display: block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .02em;
    text-transform: uppercase;
}

.portal-order-policy-strip strong,
.portal-admin-gate-card strong {
    color: var(--text-main, #0f172a);
    display: block;
    font-size: 20px;
    margin-top: 4px;
}

.portal-order-policy-strip small,
.portal-admin-gate-card small {
    color: var(--text-muted, #64748b);
    display: block;
    margin-top: 6px;
}

.portal-admin-gate-grid {
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    margin: 14px 0;
}

.portal-admin-gate-card.tone-green,
.portal-gate-pill.tone-green {
    border-color: #86efac;
    background: #f0fdf4;
}

.portal-admin-gate-card.tone-orange,
.portal-gate-pill.tone-orange {
    border-color: #fdba74;
    background: #fff7ed;
}

.portal-admin-gate-card.tone-red,
.portal-gate-pill.tone-red {
    border-color: #fca5a5;
    background: #fef2f2;
}

.portal-admin-gate-card.tone-neutral,
.portal-gate-pill.tone-neutral {
    border-color: #cbd5e1;
    background: #f8fafc;
}

.portal-draft-gate-grid {
    grid-template-columns: repeat(auto-fit, minmax(150px, max-content));
    margin-top: 10px;
}

.portal-gate-pill {
    align-items: center;
    border: 1px solid;
    border-radius: 999px;
    color: #0f172a;
    display: inline-flex;
    font-size: 12px;
    font-weight: 700;
    gap: 6px;
    line-height: 1.2;
