/* UI polish v10: final visual normalization.
   Scope: presentation only. Keep ERP data, routes, roles, and workflows untouched. */
:root,
html[data-theme="light-mono"],
html[data-theme="dark-mono"] {
    --ui10-orange: #F97316;
    --ui10-orange-2: #FB923C;
    --ui10-amber: #FBBF24;
    --ui10-cream: #FEFBEE;
    --ui10-cream-2: #FFF7ED;
    --ui10-surface: #FFFFFF;
    --ui10-surface-soft: rgba(255, 255, 255, .92);
    --ui10-ink: #111827;
    --ui10-muted: rgba(17, 24, 39, .62);
    --ui10-faint: rgba(17, 24, 39, .42);
    --ui10-line: rgba(249, 115, 22, .22);
    --ui10-line-strong: rgba(249, 115, 22, .38);
    --ui10-shadow: 0 16px 36px rgba(17, 24, 39, .08);
    --ui10-shadow-soft: 0 8px 22px rgba(17, 24, 39, .05);
    --ui10-radius: 18px;
    --ui10-radius-sm: 14px;
    --primary: var(--ui10-orange) !important;
    --primary-hover: var(--ui10-orange-2) !important;
    --primary-text: #FFFFFF !important;
    --accent: var(--ui10-orange) !important;
    --success: var(--ui10-orange) !important;
    --info: var(--ui10-orange) !important;
    --warning: var(--ui10-amber) !important;
    --danger: var(--ui10-orange) !important;
    --sidebar: var(--ui10-surface) !important;
    --sidebar-active: var(--ui10-cream-2) !important;
    --sidebar-hover: rgba(249, 115, 22, .10) !important;
    --bg: var(--ui10-cream) !important;
    --surface: var(--ui10-surface) !important;
    --text: var(--ui10-ink) !important;
    --muted: var(--ui10-muted) !important;
    color-scheme: light !important;
}

html,
body,
body.is-authenticated,
body.is-public,
.app-main,
.content-area,
.auth-page,
.public-landing {
    background:
        linear-gradient(180deg, #FFFFFF 0%, var(--ui10-cream) 100%) !important;
    color: var(--ui10-ink) !important;
}

:where(h1, h2, h3, h4, h5, h6, p, span, small, strong, label, th, td, a, button, input, select, textarea, .text-muted) {
    text-shadow: none !important;
}

:where(p, small, .text-muted, .page-description, .form-text, .topbar-subtitle, .brand-subtitle, .portal-web-subtitle) {
    color: var(--ui10-muted) !important;
}

.auth-entry-wrapper {

    justify-content: center !important;


}

.auth-panel,
.auth-card {
    width: 100% !important;
    max-width: 440px !important;
}

.auth-card {
    position: relative !important;
    overflow: hidden !important;

}

.auth-card::before {
    content: "" !important;
    position: absolute !important;
    inset: 0 0 auto 0 !important;


}

.auth-clean-brand {
    display: flex !important;
    align-items: center !important;
    gap: 12px !important;

}

.auth-clean-brand strong {
    display: block !important;

}

.auth-clean-brand span {

    font-size: .86rem !important;
}

.auth-logo,
.brand-mark,
.portal-web-brand-mark,
.public-brand span {
    color: #FFFFFF !important;
    background: linear-gradient(135deg, var(--ui10-orange), var(--ui10-orange-2)) !important;
    border: 0 !important;
    box-shadow: none !important;
}

.auth-card-header h5 {

    margin-bottom: 10px !important;

}

.auth-note {

    width: 100% !important;

    padding: 13px 16px !important;
    border: 1px solid var(--ui10-line) !important;
    border-radius: 999px !important;
    background: var(--ui10-cream-2) !important;

}

.auth-note a {
    color: var(--ui10-orange) !important;
    font-weight: 700 !important;
}

.sidebar-brand-link,
.sidebar-brand-link:hover {
    color: var(--ui10-ink) !important;
}

.brand-title,
.sidebar-label,
.sidebar-link span,
.sidebar-group-title span,
.sidebar-sublink span,
.sidebar-link,
.sidebar-group-toggle,
.sidebar-sublink,
.app-sidebar a,
.sidebar a {
    color: var(--ui10-ink) !important;
}

.sidebar-close,
.app-sidebar-toggle,
.sidebar-toggle {

    box-shadow: var(--ui10-shadow-soft) !important;
}

.sidebar-close:hover,
.app-sidebar-toggle:hover,
.sidebar-toggle:hover {


    border-color: var(--ui10-orange) !important;
}

.sidebar-backdrop,
.offcanvas-backdrop {
    background: rgba(249, 115, 22, .14) !important;
    backdrop-filter: blur(4px) !important;
}

.app-sidebar::-webkit-scrollbar,
.dropdown-menu::-webkit-scrollbar,
select::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
}

.app-sidebar::-webkit-scrollbar-track,
.dropdown-menu::-webkit-scrollbar-track,
select::-webkit-scrollbar-track {
    background: var(--ui10-cream-2) !important;
}

.app-sidebar::-webkit-scrollbar-thumb,
.dropdown-menu::-webkit-scrollbar-thumb,
select::-webkit-scrollbar-thumb {
    background: rgba(249, 115, 22, .42) !important;
    border-radius: 999px !important;
}

.topbar-status,
.topbar-icon-link,
.theme-segmented-toggle,
.user-chip,
.portal-web-user,
.portal-web-logout-button,
.public-nav a,
.portal-web-nav a {
    color: var(--ui10-ink) !important;
    background: var(--ui10-surface) !important;
    border: 1px solid var(--ui10-line) !important;
    box-shadow: none !important;
}

.dropdown-menu *,
.dropdown-menu li,
.dropdown-menu form,
.dropdown-menu .dropdown-divider {
    border-color: rgba(249, 115, 22, .12) !important;
}

.btn-primary:hover,
.btn-success:hover,
.app-btn-primary:hover,
.public-primary-action:hover,
.portal-home-primary:hover,
button[type="submit"]:hover,
input[type="submit"]:hover,
.public-nav-login:hover,
.public-nav a.active:hover,
.portal-web-nav a.active:hover {
    color: #FFFFFF !important;
    background: var(--ui10-orange-2) !important;
    border-color: var(--ui10-orange-2) !important;
}

.portal-home-balance-card *,
.portal-pt-executive-card *,
.portal-home-flow-card *,
.public-order-card * {
    color: var(--ui10-ink) !important;
}

.status-badge::before,
.badge::before,
.portal-web-role-chip::before,
.portal-hero-status::before,
.portal-home-soft-pill::before,
.public-eyebrow::before,
.page-eyebrow::before,
.eyebrow::before,
.portal-home-kicker::before,
.portal-source-pill::before,
.alert-badge::before,
.pill::before {
    background: var(--ui10-orange) !important;
}

@media (max-width: 920px) {
    .app-sidebar {

        border-top-right-radius: 0 !important;
        border-bottom-right-radius: 0 !important;
    }

    .app-sidebar:not(.is-open):not(.show) {
        box-shadow: none !important;
    }

    .sidebar-brand {
        background: #FFFFFF !important;
    }
}

