.finance-portal-proof-overview {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: 16px;
}

.finance-portal-proof-overview.compact {
    margin-bottom: 14px;
}

.finance-portal-proof-overview article {
    min-height: 118px;
    border: 1px solid var(--border-color, #d9dde5);
    border-radius: 14px;
    background: var(--card-bg, #fff);
    padding: 16px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
}

.finance-portal-proof-overview span,
.finance-erp-integration-card span {
    color: var(--muted-text, #64748b);
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0;
    text-transform: uppercase;
}

.finance-portal-proof-overview strong {
    color: var(--body-color, #111827);
    font-size: clamp(1.1rem, 1.8vw, 1.65rem);
    line-height: 1.1;
}

.finance-portal-proof-overview small {
    color: var(--muted-text, #64748b);
    font-weight: 600;
}

.finance-portal-proof-tabs {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
}

.finance-portal-proof-tabs a {
    min-height: 58px;
    border: 1px solid var(--border-color, #d9dde5);
    border-radius: 12px;
    background: var(--surface-bg, #f8fafc);
    color: var(--body-color, #111827);
    text-decoration: none;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 14px;
    font-weight: 700;
}

.finance-portal-proof-tabs a.is-active {
    background: #111827;
    color: #fff;
    border-color: #111827;
}

.finance-portal-proof-tabs strong {
    min-width: 34px;
    min-height: 30px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.72);
    color: #111827;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.95rem;
}

.finance-erp-integration-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    padding: 0 16px 16px;
}

.finance-erp-integration-grid.compact {
    grid-template-columns: repeat(8, minmax(120px, 1fr));
    overflow-x: auto;
    padding: 0 0 4px;
}

.finance-erp-integration-card {
    min-height: 150px;
    border: 1px solid var(--border-color, #d9dde5);
    border-radius: 14px;
    background: var(--card-bg, #fff);
    color: var(--body-color, #111827);
    text-decoration: none;
    padding: 14px;
    display: grid;
    grid-template-rows: auto auto auto 1fr auto;
    gap: 7px;
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.055);
}

.finance-erp-integration-grid.compact .finance-erp-integration-card {
    min-width: 142px;
    min-height: 132px;
}

.finance-erp-integration-card strong {
    color: var(--body-color, #111827);
    font-size: 1rem;
    line-height: 1.2;
}

.finance-erp-integration-card small,
.finance-erp-integration-card em {
    color: var(--muted-text, #64748b);
    font-size: 0.78rem;
    font-style: normal;
    line-height: 1.35;
}

.finance-erp-integration-card b {
    align-self: end;
    width: fit-content;
    min-width: 38px;
    min-height: 34px;
    border-radius: 999px;
    background: #eef2ff;
    color: #1e40af;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 10px;
}

.finance-erp-integration-card.status-ok {
    border-left: 4px solid #16a34a;
}

.finance-erp-integration-card.status-warning {
    border-left: 4px solid #f59e0b;
}

.finance-erp-integration-card.status-empty {
    border-left: 4px solid #94a3b8;
}

.finance-erp-integration-card.status-error,
.finance-erp-integration-card.status-blocked {
    border-left: 4px solid #dc2626;
}

.finance-portal-proof-table {
    min-width: 1180px;
}

.finance-portal-proof-table th,
.finance-portal-proof-table td {
    vertical-align: top;
}

.finance-portal-proof-table th:nth-child(1),
.finance-portal-proof-table td:nth-child(1) {
    min-width: 240px;
    max-width: 320px;
}

.finance-portal-proof-table th:nth-child(6),
