    gap: 8px;
    align-items: center;
}

.finance-proof-review-actions form {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
}

.finance-proof-review-actions input[type="text"] {
    width: 180px;
}

.finance-proof-payment-form {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.finance-proof-payment-form label {
    display: grid;
    gap: 4px;
    margin: 0;
}

.finance-proof-payment-form label span {
    color: var(--muted-text, #64748b);
    font-size: 0.72rem;
    font-weight: 700;
