        #0f172a;
}

.portal-command-pt .portal-command-hero {
    background:
        linear-gradient(135deg, rgba(15, 23, 42, .98), rgba(4, 120, 87, .94) 56%, rgba(22, 163, 74, .96)),
        #0f172a;
}

.portal-command-copy {
    display: grid;
    align-content: center;
    gap: 14px;
    min-width: 0;
    padding: 28px;
}

.portal-command-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: fit-content;
    max-width: 100%;
    padding: 7px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, .14);
    color: rgba(255, 255, 255, .86);
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
}

.portal-command-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: #22c55e;
    box-shadow: 0 0 0 4px rgba(34, 197, 94, .18);
}

.portal-command-copy h2 {
    max-width: 840px;
    margin: 0;
    font-size: clamp(28px, 4vw, 48px);
    font-weight: 700;
    line-height: 1.03;
}

.portal-command-copy p {
    max-width: 76ch;
    margin: 0;
    color: rgba(255, 255, 255, .80);
    font-size: 15px;
    font-weight: 700;
    line-height: 1.65;
}

.portal-command-guard {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    width: fit-content;
    max-width: 100%;
    padding: 10px 12px;
    border-radius: 16px;
    background: rgba(255, 255, 255, .13);
    color: rgba(255, 255, 255, .94);
    font-size: 13px;
    font-weight: 700;
}

.portal-command-guard i {
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    width: 28px;
    height: 28px;
    border-radius: 999px;
    background: rgba(255, 255, 255, .18);
}

.portal-command-proof {
    display: grid;
    align-content: end;
    gap: 8px;
    min-width: 0;
    margin: 16px;
    padding: 18px;
    border-radius: 22px;
    background: rgba(255, 255, 255, .13);
    color: #fff;
}

.portal-command-proof span {
    color: rgba(255, 255, 255, .70);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-command-proof strong {
    font-size: 22px;
    font-weight: 700;
    line-height: 1.1;
}

.portal-command-proof p {
    margin: 0;
    color: rgba(255, 255, 255, .74);
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-command-alerts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 12px;
}

.portal-command-alert {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr);
    align-items: center;
    gap: 12px;
    min-height: 74px;
    padding: 13px;
    border-radius: 18px;
    background: rgba(255, 255, 255, .92);
    color: inherit;
    text-decoration: none;
}

.portal-command-alert i {
    display: grid;
    place-items: center;
    width: 42px;
    height: 42px;
    border-radius: 15px;
    font-size: 18px;
}

.portal-command-alert span {
    min-width: 0;
}

.portal-command-alert strong,
.portal-command-alert small {
    display: block;
    overflow-wrap: anywhere;
}

.portal-command-alert strong {
    font-size: 14px;
    font-weight: 700;
}

.portal-command-alert small {
    margin-top: 4px;
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.45;
}

.portal-command-alert.is-danger i {
    background: #fee2e2;
    color: #b91c1c;
}

.portal-command-alert.is-warning i {
    background: #ffedd5;
    color: #c2410c;
}

.portal-command-alert.is-info i {
    background: #dbeafe;
    color: #0369a1;
}

.portal-command-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(164px, 1fr));
    gap: 12px;
}

.portal-command-kpi {
    display: grid;
    gap: 12px;
    min-height: 146px;
    padding: 15px;
    border-radius: 20px;
    background: rgba(255, 255, 255, .92);
}

.portal-command-kpi > div {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.portal-command-icon,
.portal-command-kpi i,
.portal-command-action > i,
.portal-command-event > i,
.portal-command-status-main > i {
    display: grid;
    place-items: center;
    flex: 0 0 auto;
}

.portal-command-icon,
.portal-command-kpi i {
    width: 42px;
    height: 42px;
    border-radius: 15px;
}

.portal-command-kpi small {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-command-kpi strong {
    font-size: 32px;
    font-weight: 700;
    line-height: 1;
}

.portal-command-kpi p {
    margin: 0;
    color: #475569;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.45;
}

.portal-command-heading {
    margin-top: 2px;
}

.portal-command-actions {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 12px;
}

.portal-command-action {
    display: grid;
    grid-template-columns: 46px minmax(0, 1fr) 22px;
    align-items: center;
    gap: 12px;
    min-height: 86px;
    padding: 14px;
    border-radius: 19px;
    background: rgba(255, 255, 255, .92);
    color: inherit;
    text-decoration: none;
}

.portal-command-action > i {
    width: 46px;
    height: 46px;
    border-radius: 16px;
    font-size: 20px;
}

.portal-command-action span {
    display: grid;
    gap: 4px;
    min-width: 0;
}

.portal-command-action strong {
    overflow: hidden;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-command-action small {
    display: -webkit-box;
    overflow: hidden;
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.38;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.portal-command-action em {
    color: #94a3b8;
    font-style: normal;
}

.portal-command-action.is-disabled {
    opacity: .76;
}

.portal-command-action.is-disabled > i {
    background: #e2e8f0;
    color: #64748b;
}

.portal-command-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(320px, .75fr);
    gap: 14px;
}

.portal-command-grid.three {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.portal-command-panel {
    display: grid;
    gap: 13px;
    min-width: 0;
    padding: 16px;
    border-radius: 22px;
    background: rgba(255, 255, 255, .92);
}

.portal-command-panel.compact {
    align-content: start;
}

.portal-command-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.portal-command-panel-head span {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-command-panel-head h3 {
    margin: 2px 0 0;
    font-size: 18px;
    font-weight: 700;
    line-height: 1.15;
}

.portal-command-panel-head > i {
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    width: 42px;
    height: 42px;
    border-radius: 15px;
    background: #f1f5f9;
    color: #334155;
}

.portal-command-timeline,
.portal-command-status-list,
.portal-command-list,
.portal-command-sources {
    display: grid;
    gap: 10px;
}

.portal-command-event {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 10px;
    min-height: 66px;
    padding: 11px;
    border-radius: 16px;
    background: rgba(248, 250, 252, .92);
    color: inherit;
    text-decoration: none;
}

.portal-command-event > i {
    width: 42px;
    height: 42px;
    border-radius: 15px;
    font-size: 18px;
}

.portal-command-event span {
    display: grid;
    gap: 3px;
    min-width: 0;
}

.portal-command-event strong,
.portal-command-event small {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-command-event strong {
    font-size: 13px;
    font-weight: 700;
}

.portal-command-event small {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
}

.portal-command-event b,
.portal-command-event time,
.portal-command-status-tags span,
.portal-command-list b,
.portal-command-sources em {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 26px;
    padding: 0 9px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #334155;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

.portal-command-event time {
    color: #64748b;
}

.portal-command-empty {
    display: grid;
    place-items: center;
    min-height: 220px;
    padding: 24px;
    border: 1px dashed rgba(148, 163, 184, .40);
    border-radius: 18px;
    background: rgba(248, 250, 252, .72);
    text-align: center;
}

.portal-command-empty i {
    display: grid;
    place-items: center;
    width: 52px;
    height: 52px;
    margin-bottom: 8px;
    border-radius: 18px;
    background: #dbeafe;
    color: #0369a1;
    font-size: 22px;
}

.portal-command-empty strong {
    font-size: 16px;
    font-weight: 700;
}

.portal-command-empty p {
    max-width: 380px;
    margin: 5px 0 10px;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-command-empty a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 38px;
    padding: 0 14px;
    border-radius: 999px;
    background: #0f172a;
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    text-decoration: none;
}

.portal-command-status {
    display: grid;
    gap: 10px;
    padding: 12px;
    border-radius: 17px;
    background: rgba(248, 250, 252, .92);
}

.portal-command-status-main {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
}

.portal-command-status-main > i {
    width: 42px;
    height: 42px;
    border-radius: 15px;
    font-size: 18px;
}

.portal-command-status-main span {
    min-width: 0;
}

.portal-command-status-main strong,
.portal-command-status-main small {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-command-status-main strong {
    font-size: 14px;
    font-weight: 700;
}

.portal-command-status-main small {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
}

.portal-command-status-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
}

.portal-command-status-tags span b {
    margin-left: 5px;
}

.portal-command-list article {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 5px 10px;
    min-height: 58px;
    padding: 10px 0;
    border-bottom: 1px solid rgba(148, 163, 184, .18);
}

.portal-command-list article:last-child {
    border-bottom: 0;
}

.portal-command-list strong {
    overflow: hidden;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-command-list span {
    display: block;
    overflow: hidden;
    grid-column: 1 / 2;
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.35;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-command-list b {
    grid-row: 1 / span 2;
    grid-column: 2 / 3;
    align-self: center;
}

.portal-command-soft-empty {
    min-height: 70px;
    padding: 14px;
    border-radius: 15px;
    background: #f8fafc;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-command-sources {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.portal-command-sources article {
    display: grid;
    gap: 7px;
    min-height: 142px;
    padding: 13px;
    border-radius: 17px;
    background: rgba(248, 250, 252, .92);
}

.portal-command-sources strong {
    font-size: 13px;
    font-weight: 700;
}

.portal-command-sources span {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.42;
}

.portal-command-sources b {
    align-self: end;
    font-size: 22px;
    font-weight: 700;
}

.tone-green .portal-command-icon,
.tone-green > i,
.portal-command-kpi.tone-green i,
.portal-command-action.tone-green > i,
.portal-command-event.tone-green > i,
.portal-command-status.tone-green .portal-command-status-main > i {
    background: #dcfce7;
    color: #047857;
}

.tone-blue .portal-command-icon,
.tone-blue > i,
.portal-command-kpi.tone-blue i,
.portal-command-action.tone-blue > i,
.portal-command-event.tone-blue > i,
.portal-command-status.tone-blue .portal-command-status-main > i {
    background: #dbeafe;
    color: #0369a1;
}

.tone-orange .portal-command-icon,
.tone-orange > i,
.portal-command-kpi.tone-orange i,
.portal-command-action.tone-orange > i,
.portal-command-event.tone-orange > i,
.portal-command-status.tone-orange .portal-command-status-main > i {
    background: #ffedd5;
    color: #c2410c;
}

.tone-purple .portal-command-icon,
.tone-purple > i,
.portal-command-kpi.tone-purple i,
.portal-command-action.tone-purple > i,
.portal-command-event.tone-purple > i,
.portal-command-status.tone-purple .portal-command-status-main > i {
    background: #ede9fe;
    color: #7c3aed;
}

.tone-slate .portal-command-icon,
.tone-slate > i,
.portal-command-kpi.tone-slate i,
.portal-command-action.tone-slate > i,
.portal-command-event.tone-slate > i,
.portal-command-status.tone-slate .portal-command-status-main > i {
    background: #e2e8f0;
    color: #334155;
}

.tone-red .portal-command-icon,
.tone-red > i,
.portal-command-kpi.tone-red i,
.portal-command-action.tone-red > i,
.portal-command-event.tone-red > i,
.portal-command-status.tone-red .portal-command-status-main > i {
    background: #ffe4e6;
    color: #be123c;
}

[data-theme="dark-mono"] .portal-command-alert,
[data-theme="dark-mono"] .portal-command-kpi,
[data-theme="dark-mono"] .portal-command-action,
[data-theme="dark-mono"] .portal-command-panel,
[data-theme="dark-mono"] .portal-command-event,
[data-theme="dark-mono"] .portal-command-status,
[data-theme="dark-mono"] .portal-command-sources article {
    background: rgba(15, 23, 42, .84);
    border-color: rgba(148, 163, 184, .18);
}

[data-theme="dark-mono"] .portal-command-alert small,
[data-theme="dark-mono"] .portal-command-kpi p,
[data-theme="dark-mono"] .portal-command-action small,
[data-theme="dark-mono"] .portal-command-event small,
[data-theme="dark-mono"] .portal-command-status-main small,
[data-theme="dark-mono"] .portal-command-list span,
[data-theme="dark-mono"] .portal-command-sources span,
[data-theme="dark-mono"] .portal-command-soft-empty,
[data-theme="dark-mono"] .portal-command-empty p {
    color: #cbd5e1;
}

[data-theme="dark-mono"] .portal-command-panel-head > i,
[data-theme="dark-mono"] .portal-command-event b,
[data-theme="dark-mono"] .portal-command-event time,
[data-theme="dark-mono"] .portal-command-status-tags span,
[data-theme="dark-mono"] .portal-command-list b,
[data-theme="dark-mono"] .portal-command-sources em,
[data-theme="dark-mono"] .portal-command-soft-empty,
[data-theme="dark-mono"] .portal-command-empty {
    background: rgba(2, 6, 23, .62);
    color: #e2e8f0;
}

@media (max-width: 980px) {
    .portal-command-hero,
    .portal-command-grid,
    .portal-command-grid.three {
        grid-template-columns: 1fr;
    }

    .portal-command-proof {
        align-content: start;
    }
}

@media (max-width: 720px) {
    .portal-command-center {
        gap: 14px;
        margin-top: 14px;
    }

    .portal-command-copy {
        padding: 22px;
    }

    .portal-command-copy h2 {
        font-size: 26px;
    }

    .portal-command-copy p {
        font-size: 14px;
    }

    .portal-command-guard {
        align-items: flex-start;
        width: 100%;
    }

    .portal-command-proof {
        margin: 0 12px 12px;
    }

    .portal-command-kpis,
    .portal-command-alerts,
    .portal-command-actions,
    .portal-command-sources {
        grid-template-columns: 1fr;
    }

    .portal-command-action {
        min-height: 78px;
    }

    .portal-command-event {
        grid-template-columns: 42px minmax(0, 1fr);
    }

    .portal-command-event b,
    .portal-command-event time {
        justify-self: start;
        grid-column: 2 / 3;
    }

    .portal-command-list article {
        grid-template-columns: 1fr;
    }

    .portal-command-list b {
        justify-self: start;
        grid-row: auto;
        grid-column: auto;
    }
}

/* ==================================================
   Portal operational feature pages
   These classes replace the older thin portal pages with integrated, role-safe
   web surfaces. All pages remain data-backed by existing ERP models.
   ================================================== */

.portal-workflow-page,
.portal-ledger-page,
.portal-directory-page,
.portal-service-page,
.portal-calendar-page {
    display: grid;
    gap: 18px;
}

.portal-workflow-hero,
.portal-ledger-hero,
.portal-directory-hero,
.portal-service-hero {
    background:
        linear-gradient(135deg, rgba(15, 23, 42, .98), rgba(2, 132, 199, .92) 56%, rgba(22, 163, 74, .94)),
        #0f172a;
}

.portal-workflow-panel,
.portal-order-builder,
.portal-order-submit-card,
.portal-blocked-state,
.portal-empty-state,
.portal-record-card,
.portal-ledger-summary article,
.portal-ledger-card,
.portal-directory-summary article,
.portal-directory-card,
.portal-service-summary article,
.portal-service-card,
.portal-document-card,
.portal-calendar-card {
    border: 1px solid rgba(148, 163, 184, .22);
    background: rgba(255, 255, 255, .92);
    box-shadow: 0 16px 42px rgba(15, 23, 42, .08);
}

.portal-workflow-panel {
    display: grid;
    gap: 14px;
    align-content: start;
    min-width: 0;
    padding: 18px;
    border-radius: 22px;
}

.portal-workflow-panel.primary {
    background:
        linear-gradient(135deg, rgba(255, 255, 255, .96), rgba(240, 253, 244, .92)),
        #fff;
}

.portal-workflow-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.portal-workflow-panel-head > span,
.portal-workflow-panel-head > strong {
    overflow-wrap: anywhere;
}

.portal-workflow-panel h2 {
    margin: 0;
    font-size: clamp(24px, 3vw, 34px);
    font-weight: 700;
    line-height: 1.08;
}

.portal-workflow-panel p {
    margin: 0;
    color: #64748b;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.6;
}

.portal-workflow-steps,
.portal-order-progress {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 8px;
}

.portal-workflow-steps div,
.portal-order-progress div {
    display: grid;
    justify-items: center;
    gap: 7px;
    min-width: 0;
    padding: 11px 8px;
    border: 1px solid rgba(148, 163, 184, .20);
    border-radius: 16px;
    background: #f8fafc;
    color: #64748b;
    text-align: center;
}

.portal-workflow-steps div.is-active,
.portal-order-progress div.is-active {
    background: #dcfce7;
    color: #047857;
    border-color: rgba(22, 163, 74, .28);
}

.portal-workflow-steps i,
.portal-order-progress i {
    font-size: 18px;
}

.portal-workflow-steps span,
.portal-order-progress span,
.portal-order-progress small {
    display: block;
    overflow: hidden;
    width: 100%;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-order-progress small {
    color: inherit;
    opacity: .72;
}

.portal-workflow-facts,
.portal-directory-summary,
.portal-service-summary {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
    gap: 10px;
}

.portal-workflow-facts article,
.portal-directory-summary article,
.portal-service-summary article {
    display: grid;
    gap: 4px;
    min-height: 96px;
    padding: 13px;
    border-radius: 18px;
}

.portal-workflow-facts span,
.portal-directory-summary span,
.portal-service-summary span,
.portal-ledger-summary span {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-workflow-facts strong,
.portal-directory-summary strong,
.portal-service-summary strong,
.portal-ledger-summary strong {
    font-size: 26px;
    font-weight: 700;
    line-height: 1;
}

.portal-order-builder {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(260px, 340px);
    gap: 14px;
    padding: 16px;
    border-radius: 22px;
}

.portal-order-builder-main {
    display: grid;
    gap: 14px;
    min-width: 0;
}

.portal-form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.portal-form-grid label,
.portal-form-wide {
    display: grid;
    gap: 7px;
    min-width: 0;
}

.portal-form-grid span,
.portal-form-wide span {
    color: #475569;
    font-size: 12px;
    font-weight: 700;
}

.portal-form-grid input,
.portal-form-grid select,
.portal-form-wide textarea {
    width: 100%;
    min-height: 48px;
    padding: 11px 13px;
    border: 1px solid rgba(148, 163, 184, .32);
    border-radius: 14px;
    background: #f8fafc;
    color: inherit;
    font: inherit;
    font-weight: 700;
}

.portal-order-submit-card {
    display: grid;
    align-content: center;
    justify-items: start;
    gap: 12px;
    padding: 18px;
    border-radius: 20px;
    background: #0f172a;
    color: #fff;
}

.portal-order-submit-card > i {
    display: grid;
    place-items: center;
    width: 52px;
    height: 52px;
    border-radius: 18px;
    background: rgba(255, 255, 255, .14);
    font-size: 24px;
}

.portal-order-submit-card h3 {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
}

.portal-order-submit-card p {
    margin: 0;
    color: rgba(255, 255, 255, .76);
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-blocked-state,
.portal-empty-state {
    display: grid;
    grid-template-columns: 54px minmax(0, 1fr);
    align-items: center;
    gap: 14px;
    padding: 18px;
    border-radius: 20px;
}

.portal-empty-state {
    grid-template-columns: 1fr;
    justify-items: center;


}

.portal-blocked-state i,
.portal-empty-state i {
    display: grid;
    place-items: center;
    width: 54px;
    height: 54px;
    border-radius: 18px;
    background: #ffedd5;
    color: #c2410c;
    font-size: 24px;
}

.portal-empty-state i {
    background: #dbeafe;
    color: #0369a1;
}

.portal-blocked-state h2,
.portal-empty-state strong {
    margin: 0;
    font-size: 18px;
    font-weight: 700;
}

.portal-blocked-state p,
.portal-empty-state p {
    margin: 4px 0 0;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-record-list,
.portal-ledger-list,
.portal-service-list,
.portal-calendar-list {
    display: grid;
    gap: 12px;
}

.portal-record-card,
.portal-ledger-card,
.portal-service-card,
.portal-calendar-card {
    min-width: 0;
    padding: 15px;
    border-radius: 20px;
}

.portal-record-card,
.portal-ledger-card {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 14px;
}

.portal-record-main,
.portal-ledger-card-main {
    display: grid;
    grid-template-columns: 48px minmax(0, 1fr);
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.portal-record-icon {
    display: grid;
    place-items: center;
    width: 48px;
    height: 48px;
    border-radius: 17px;
    background: #dcfce7;
    color: #047857;
    font-size: 20px;
}

.portal-record-main h3,
.portal-ledger-card-main h3,
.portal-service-card-main h3,
.portal-directory-content h3,
.portal-document-body h3,
.portal-calendar-card h3 {
    overflow: hidden;
    margin: 0;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-record-main p,
.portal-ledger-card-main p,
.portal-service-card-main p,
.portal-directory-content p,
.portal-document-body p,
.portal-calendar-card p {
    overflow: hidden;
    margin: 5px 0 0;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.45;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.portal-status-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 32px;
    padding: 0 12px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #334155;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}

.portal-ledger-summary {
    display: grid;
    grid-template-columns: minmax(280px, 1.4fr) repeat(4, minmax(140px, 1fr));
    gap: 12px;
}

.portal-ledger-summary article,
.portal-directory-summary article,
.portal-service-summary article {
    align-content: center;
}

.portal-ledger-summary article,
.portal-service-summary article.primary {
    border-radius: 20px;
}

.portal-ledger-total,
.portal-service-summary article.primary {
    background:
        linear-gradient(135deg, rgba(15, 23, 42, .98), rgba(15, 118, 110, .92)),
        #0f172a !important;
    color: #fff;
}

.portal-ledger-total span,
.portal-ledger-total small,
.portal-ledger-total p,
.portal-service-summary article.primary span,
.portal-service-summary article.primary small {
    color: rgba(255, 255, 255, .76);
}

.portal-ledger-total p {
    margin: 8px 0 0;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
}

.portal-ledger-card {
    grid-template-columns: minmax(0, 1fr) minmax(240px, auto) auto;
}

.portal-ledger-card.compact {
    grid-template-columns: minmax(0, 1fr) minmax(160px, auto);
}

.portal-ledger-amounts {
    display: grid;
    grid-template-columns: repeat(3, minmax(86px, 1fr));
    gap: 8px;
}

.portal-ledger-amounts.single {
    grid-template-columns: minmax(120px, 1fr);
}

.portal-ledger-amounts div {
    display: grid;
    gap: 3px;
    min-width: 0;
    padding: 9px;
    border-radius: 14px;
    background: #f8fafc;
}

.portal-ledger-amounts span {
    color: #64748b;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-ledger-amounts strong {
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
}

.portal-ledger-actions {
    display: flex;
    justify-content: flex-end;
}

.portal-directory-grid,
.portal-document-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 12px;
}

.portal-directory-card,
.portal-document-card {
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr);
    gap: 13px;
    min-width: 0;
    padding: 15px;
    border-radius: 20px;
}

.portal-directory-card.wide {
    grid-column: span 1;
}

.portal-directory-avatar {
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    border-radius: 19px;
    background: #dbeafe;
    color: #0369a1;
    font-size: 22px;
    font-weight: 700;
}

.portal-location-stack {
    display: grid;
    gap: 7px;
    margin-top: 10px;
}

.portal-location-stack span {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: 32px;
    padding: 0 10px;
    border-radius: 999px;
    background: #f8fafc;
    color: #475569;
    font-size: 12px;
    font-weight: 700;
}

.portal-service-card {
    display: grid;
    grid-template-columns: 50px minmax(0, 1fr);
    gap: 13px;
}

.portal-service-card-icon {
    display: grid;
    place-items: center;
    width: 50px;
    height: 50px;
    border-radius: 17px;
    background: #dbeafe;
    color: #0369a1;
    font-size: 21px;
}

.portal-service-card.priority-critical .portal-service-card-icon,
.portal-service-card.priority-warning .portal-service-card-icon {
    background: #ffedd5;
    color: #c2410c;
}

.portal-service-card-title {
    display: flex;
    justify-content: space-between;
    gap: 12px;
}

.portal-service-card-title strong {
    align-self: flex-start;
    padding: 6px 9px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #334155;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

.portal-inline-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 12px;
}

.portal-inline-actions form {
    margin: 0;
}

.portal-action-link.secondary {
    background: #fff;
    color: #0f172a;
}

.portal-document-card {
    grid-template-columns: 72px minmax(0, 1fr);
}

.portal-calendar-list {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.portal-calendar-card {
    display: grid;
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 13px;
}

.portal-calendar-card time {
    display: grid;
    place-items: center;
    align-content: center;
    width: 72px;
    min-height: 82px;
    border-radius: 18px;
    background: #0f172a;
    color: #fff;
}

.portal-calendar-card time strong {
    font-size: 28px;
    font-weight: 700;
    line-height: 1;
}

.portal-calendar-card time span {
    margin-top: 4px;
    color: rgba(255, 255, 255, .72);
    font-size: 11px;
    font-weight: 700;
}

[data-theme="dark-mono"] .portal-workflow-panel,
[data-theme="dark-mono"] .portal-order-builder,
[data-theme="dark-mono"] .portal-blocked-state,
[data-theme="dark-mono"] .portal-empty-state,
[data-theme="dark-mono"] .portal-record-card,
[data-theme="dark-mono"] .portal-ledger-summary article,
[data-theme="dark-mono"] .portal-ledger-card,
[data-theme="dark-mono"] .portal-directory-summary article,
[data-theme="dark-mono"] .portal-directory-card,
[data-theme="dark-mono"] .portal-service-summary article,
[data-theme="dark-mono"] .portal-service-card,
[data-theme="dark-mono"] .portal-document-card,
[data-theme="dark-mono"] .portal-calendar-card {
    background: rgba(15, 23, 42, .84);
    border-color: rgba(148, 163, 184, .18);
}

[data-theme="dark-mono"] .portal-workflow-panel.primary,
[data-theme="dark-mono"] .portal-ledger-amounts div,
[data-theme="dark-mono"] .portal-workflow-steps div,
[data-theme="dark-mono"] .portal-order-progress div,
[data-theme="dark-mono"] .portal-location-stack span,
[data-theme="dark-mono"] .portal-service-card-title strong,
[data-theme="dark-mono"] .portal-status-pill,
[data-theme="dark-mono"] .portal-action-link.secondary,
[data-theme="dark-mono"] .portal-form-grid input,
[data-theme="dark-mono"] .portal-form-grid select,
[data-theme="dark-mono"] .portal-form-wide textarea {
    background: rgba(2, 6, 23, .62);
    color: #e2e8f0;
    border-color: rgba(148, 163, 184, .18);
}

[data-theme="dark-mono"] .portal-workflow-panel p,
[data-theme="dark-mono"] .portal-blocked-state p,
[data-theme="dark-mono"] .portal-empty-state p,
[data-theme="dark-mono"] .portal-record-main p,
[data-theme="dark-mono"] .portal-ledger-card-main p,
[data-theme="dark-mono"] .portal-service-card-main p,
[data-theme="dark-mono"] .portal-directory-content p,
[data-theme="dark-mono"] .portal-document-body p,
[data-theme="dark-mono"] .portal-calendar-card p {
    color: #cbd5e1;
}

@media (max-width: 1100px) {
    .portal-ledger-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .portal-ledger-total {
        grid-column: 1 / -1;
    }

    .portal-ledger-card,
    .portal-ledger-card.compact {
        grid-template-columns: 1fr;
    }

    .portal-ledger-actions {
        justify-content: flex-start;
    }
}

@media (max-width: 820px) {
    .portal-order-builder {
        grid-template-columns: 1fr;
    }

    .portal-workflow-steps,
    .portal-order-progress {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .portal-form-grid,
    .portal-ledger-summary,
    .portal-service-summary,
    .portal-directory-summary {
        grid-template-columns: 1fr;
    }

    .portal-record-card,
    .portal-ledger-card-main,
    .portal-record-main,
    .portal-service-card,
    .portal-directory-card,
    .portal-document-card,
    .portal-calendar-card,
    .portal-blocked-state {
        grid-template-columns: 1fr;
    }

    .portal-ledger-amounts {
        grid-template-columns: 1fr;
    }

    .portal-service-card-title {
        align-items: flex-start;
        flex-direction: column;
    }

    .portal-record-main h3,
    .portal-ledger-card-main h3,
    .portal-service-card-main h3,
    .portal-directory-content h3,
    .portal-document-body h3,
    .portal-calendar-card h3,
    .portal-record-main p,
    .portal-ledger-card-main p,
    .portal-service-card-main p,
    .portal-directory-content p,
    .portal-document-body p,
    .portal-calendar-card p {
        white-space: normal;
    }
}

/*
   Portal care, document, notification, and admin bridge polish
   These views are integrated read/write shells over CustomerComplaint, DigitalAttachment, Notification, and DailyOrder.
*/

.portal-care-page,
.portal-document-page,
.portal-notification-page {
    display: grid;
    gap: 22px;
}

.portal-care-hero {
    align-items: center;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
}

.portal-care-summary,
.portal-document-summary,
.portal-notification-summary {
    grid-template-columns: minmax(260px, 1.35fr) repeat(4, minmax(0, 1fr));
}

.portal-care-form,
.portal-evidence-upload {
    background: rgba(255, 255, 255, .9);
    border: 1px solid rgba(15, 23, 42, .1);
    border-radius: 24px;
    box-shadow: 0 18px 46px rgba(15, 23, 42, .06);
    display: grid;
    gap: 14px;
    padding: 20px;
}

.portal-care-form > p {
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.45;
    margin: 0;
}

.portal-care-list {
    display: grid;
    gap: 14px;
}

.portal-care-card {
    background: rgba(255, 255, 255, .9);
    border: 1px solid rgba(15, 23, 42, .1);
    border-radius: 24px;
    box-shadow: 0 18px 46px rgba(15, 23, 42, .06);
    display: grid;
    gap: 16px;
    padding: 18px;
}

.portal-care-card.status-open {
    border-left: 5px solid #f59e0b;
}

.portal-care-card.status-in_progress {
    border-left: 5px solid #0ea5e9;
}

.portal-care-card.status-resolved,
.portal-care-card.status-closed {
    border-left: 5px solid #10b981;
}

.portal-care-card-main {
    align-items: start;
    display: grid;
    gap: 14px;
    grid-template-columns: auto minmax(0, 1fr);
}

.portal-care-card-main h3,
.portal-return-card h3 {
    color: #020617;
    font-size: 18px;
    font-weight: 700;
    line-height: 1.25;
    margin: 0 0 6px;
    overflow-wrap: anywhere;
}

.portal-care-card-main p,
.portal-return-card p {
    color: #475569;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;
    margin: 0 0 8px;
}

.portal-care-resolution {
    background: rgba(16, 185, 129, .1);
    border: 1px solid rgba(16, 185, 129, .22);
    border-radius: 18px;
    display: grid;
    gap: 4px;
    padding: 12px;
}

.portal-care-resolution strong {
    color: #047857;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-care-resolution span {
    color: #064e3b;
    font-size: 13px;
    font-weight: 700;
}

.portal-evidence-upload {
    box-shadow: none;
    grid-template-columns: minmax(180px, 1fr) minmax(180px, 1fr) auto;
    padding: 14px;
}

.portal-evidence-upload label {
    display: grid;
    gap: 7px;
}

.portal-evidence-upload label span {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-evidence-upload input,
.portal-care-form input,
.portal-care-form select,
.portal-care-form textarea {
    background: #fff;
    border: 1px solid rgba(15, 23, 42, .13);
    border-radius: 16px;
    color: #0f172a;
    font: inherit;
    font-weight: 700;
    outline: none;
    padding: 12px 13px;
    width: 100%;
}

.portal-return-category-grid {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.portal-return-category-grid article {
    background: rgba(255, 255, 255, .88);
    border: 1px solid rgba(15, 23, 42, .1);
    border-radius: 20px;
    padding: 16px;
}

.portal-return-category-grid span,
.portal-return-category-grid strong {
    display: block;
}

.portal-return-category-grid span {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-return-category-grid strong {
    color: #020617;
    font-size: 28px;
    font-weight: 700;
    margin-top: 8px;
}

.portal-notification-card.priority-critical {
    border-left: 5px solid #ef4444;
}

.portal-notification-card.priority-warning {
    border-left: 5px solid #f59e0b;
}

.portal-notification-card.priority-info {
    border-left: 5px solid #0ea5e9;
}

.portal-admin-bridge-page {
    display: grid;
    gap: 18px;
}

.portal-admin-draft-list {
    display: grid;
    gap: 14px;
}

.portal-admin-draft-card.is-ready {
    border-left: 5px solid #10b981;
}

.portal-admin-draft-card.is-blocked {
    border-left: 5px solid #ef4444;
}

.portal-admin-draft-head {
    align-items: start;
    display: grid;
    gap: 18px;
    grid-template-columns: minmax(0, 1fr) minmax(220px, auto);
    margin-bottom: 16px;
}

.portal-admin-draft-head h2 {
    color: #020617;
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 0;
    margin: 10px 0 4px;
}

.portal-admin-draft-head p,
.portal-admin-draft-source span,
.portal-admin-draft-source small,
.portal-admin-review-grid span {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
}

.portal-admin-draft-source {
    background: rgba(248, 250, 252, .92);
    border: 1px solid rgba(15, 23, 42, .1);
    border-radius: 18px;
    display: grid;
    gap: 4px;
    padding: 14px;
}

.portal-admin-draft-source strong {
    color: #020617;
    font-size: 16px;
    font-weight: 700;
}

.portal-admin-review-grid {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    margin-bottom: 16px;
}

.portal-admin-review-grid div {
    background: rgba(248, 250, 252, .92);
    border: 1px solid rgba(15, 23, 42, .08);
    border-radius: 16px;
    min-width: 0;
    padding: 12px;
}

.portal-admin-review-grid strong {
    color: #020617;
    display: block;
    font-size: 14px;
    font-weight: 700;
    margin-top: 4px;
    overflow-wrap: anywhere;
}

.portal-admin-note {
    background: rgba(14, 165, 233, .09);
    border: 1px solid rgba(14, 165, 233, .22);
    border-radius: 16px;
    color: #0f172a;
    font-weight: 700;
    margin-bottom: 16px;
    padding: 12px 14px;
}

.portal-admin-actions {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.portal-admin-actions form {
    align-items: center;
    background: rgba(248, 250, 252, .92);
    border: 1px solid rgba(15, 23, 42, .08);
    border-radius: 16px;
    display: grid;
    gap: 10px;
    grid-template-columns: minmax(0, 1fr) auto;
    padding: 12px;
}

[data-theme="dark-mono"] .portal-care-form,
[data-theme="dark-mono"] .portal-care-card,
