    display: grid;
    gap: 8px;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    padding: 8px;
}

.portal-tracking-stage-strip div {
    align-items: center;
    border-radius: 999px;
    color: #64748b;
    display: flex;
    font-size: 13px;
    font-weight: 700;
    gap: 8px;
    justify-content: center;
    min-height: 42px;
}

.portal-tracking-stage-strip div.is-active {
    background: #dcfce7;
    color: #166534;
}

.portal-tracking-card {
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, .24);
    border-radius: 24px;
    box-shadow: 0 18px 55px rgba(15, 23, 42, .07);
    display: grid;
    gap: 18px;
    padding: 20px;
}

.portal-tracking-card header {
    align-items: start;
    display: flex;
    gap: 16px;
    justify-content: space-between;
}

.portal-tracking-card h3,
.portal-contract-health-card h3 {
    color: #020617;
    font-size: 20px;
    font-weight: 700;
    line-height: 1.25;
    margin: 0;
    overflow-wrap: anywhere;
}

.portal-tracking-card p,
.portal-contract-health-card p {
    color: #64748b;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.45;
    margin: 5px 0 0;
}

.portal-tracking-card small {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
}

.portal-tracking-progress {
    background: #f8fafc;
    border-radius: 18px;
    padding: 12px;
}

.portal-tracking-detail-grid {
    display: grid;
    gap: 10px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.portal-tracking-detail-grid div {
    background: #f8fafc;
    border: 1px solid rgba(148, 163, 184, .18);
    border-radius: 16px;
    display: grid;
    gap: 4px;
    padding: 13px;
}

.portal-tracking-detail-grid span,
.portal-tracking-detail-grid small {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
}

.portal-tracking-detail-grid strong {
    color: #0f172a;
    font-size: 14px;
    font-weight: 700;
    overflow-wrap: anywhere;
}

.portal-tracking-note {
    align-items: center;
    background: #eff6ff;
    border: 1px solid #bfdbfe;
    border-radius: 18px;
    color: #1d4ed8;
    display: flex;
    gap: 12px;
    padding: 13px 15px;
}

.portal-tracking-note.is-warning {
    background: #fff7ed;
    border-color: #fed7aa;
    color: #c2410c;
}

.portal-tracking-note span {
    flex: 1;
    font-size: 13px;
    font-weight: 700;
}

.portal-tracking-note a {
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, .24);
    border-radius: 999px;
    color: inherit;
    font-size: 12px;
    font-weight: 700;
    padding: 9px 12px;
    text-decoration: none;
    white-space: nowrap;
}

.portal-contract-finance-strip {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.portal-contract-health-list {
    display: grid;
    gap: 14px;
}

.portal-contract-health-card {
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, .24);
    border-left: 6px solid #94a3b8;
    border-radius: 24px;
    box-shadow: 0 18px 55px rgba(15, 23, 42, .07);
    display: grid;
    gap: 16px;
    padding: 18px;
}

.portal-contract-health-card.tone-green {
    border-left-color: #22c55e;
}

.portal-contract-health-card.tone-orange {
    border-left-color: #f97316;
}

.portal-contract-health-card.tone-red {
    border-left-color: #ef4444;
}

.portal-contract-health-card.tone-purple {
    border-left-color: #8b5cf6;
}

.portal-contract-health-main {
    align-items: start;
    display: grid;
    gap: 14px;
    grid-template-columns: auto minmax(0, 1fr);
}

.portal-contract-health-meta {
    display: grid;
    gap: 10px;
    grid-template-columns: 1.4fr .7fr 1fr;
}

.portal-contract-health-meta div {
    background: #f8fafc;
    border: 1px solid rgba(148, 163, 184, .18);
    border-radius: 16px;
    display: grid;
    gap: 5px;
    padding: 13px;
}

.portal-contract-health-meta span {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-contract-health-meta strong {
    color: #020617;
    font-size: 14px;
    font-weight: 700;
    overflow-wrap: anywhere;
}

.portal-calendar-section-grid {
    display: grid;
    gap: 14px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.portal-calendar-section {
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, .24);
    border-radius: 24px;
    box-shadow: 0 18px 55px rgba(15, 23, 42, .06);
    display: grid;
    gap: 12px;
    min-width: 0;
    padding: 18px;
}

.portal-section-heading.compact {
    align-items: center;
    display: flex;
    gap: 12px;
    justify-content: space-between;
}

.portal-section-heading.compact h2 {
    align-items: center;
    display: inline-flex;
    gap: 8px;
}

.portal-calendar-mini-list {
    display: grid;
    gap: 10px;
}

.portal-calendar-mini-list .portal-calendar-card {
    box-shadow: none;
}

.portal-soft-empty {
    background: #f8fafc;
    border: 1px dashed rgba(148, 163, 184, .4);
    border-radius: 16px;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
    padding: 16px;
}

.portal-precheck-card {
    align-items: center;
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, .24);
    border-left: 6px solid #94a3b8;
    border-radius: 24px;
    box-shadow: 0 18px 55px rgba(15, 23, 42, .07);
    display: grid;
    gap: 18px;
    grid-template-columns: minmax(0, 1fr) minmax(360px, .8fr) auto;
    margin-bottom: 18px;
    padding: 18px;
}

.portal-precheck-card.tone-green {
    border-left-color: #22c55e;
}

.portal-precheck-card.tone-orange {
    border-left-color: #f97316;
}

.portal-precheck-card.tone-red {
    border-left-color: #ef4444;
}

.portal-precheck-card h2 {
    color: #020617;
    font-size: 22px;
    font-weight: 700;
    line-height: 1.2;
    margin: 10px 0 6px;
}

.portal-precheck-card p {
    color: #64748b;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;
    margin: 0;
}

.portal-precheck-grid {
    display: grid;
    gap: 10px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.portal-precheck-grid article {
    background: #f8fafc;
    border: 1px solid rgba(148, 163, 184, .2);
    border-radius: 16px;
    display: grid;
    gap: 4px;
    min-height: 86px;
    padding: 12px;
}

.portal-precheck-grid span {
    color: #64748b;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.portal-precheck-grid strong {
    color: #020617;
    font-size: 22px;
    font-weight: 700;
    line-height: 1;
}

.portal-precheck-grid small {
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.3;
}

.portal-admin-workqueue-grid {
    display: grid;
    gap: 18px;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.portal-admin-workqueue-grid > section {
    min-width: 0;
}

[data-theme="dark-mono"] .portal-web-user-name,
[data-theme="dark-mono"] .portal-role-focus-card strong,
[data-theme="dark-mono"] .portal-tracking-overview strong,
[data-theme="dark-mono"] .portal-contract-summary strong,
[data-theme="dark-mono"] .portal-calendar-summary strong,
[data-theme="dark-mono"] .portal-contract-finance-strip strong,
[data-theme="dark-mono"] .portal-tracking-card h3,
[data-theme="dark-mono"] .portal-contract-health-card h3,
[data-theme="dark-mono"] .portal-tracking-detail-grid strong,
[data-theme="dark-mono"] .portal-contract-health-meta strong {
    color: #e2e8f0;
}

[data-theme="dark-mono"] .portal-web-role-chip {
    background: rgba(37, 99, 235, .14);
    border-color: rgba(96, 165, 250, .28);
    color: #93c5fd;
}

[data-theme="dark-mono"] .portal-role-focus-card,
[data-theme="dark-mono"] .portal-tracking-overview article,
[data-theme="dark-mono"] .portal-contract-summary article,
[data-theme="dark-mono"] .portal-calendar-summary article,
[data-theme="dark-mono"] .portal-contract-finance-strip article,
[data-theme="dark-mono"] .portal-tracking-stage-strip,
[data-theme="dark-mono"] .portal-tracking-card,
[data-theme="dark-mono"] .portal-contract-health-card,
[data-theme="dark-mono"] .portal-calendar-section,
[data-theme="dark-mono"] .portal-precheck-card {
    background: rgba(15, 23, 42, .84);
    border-color: rgba(148, 163, 184, .18);
}

[data-theme="dark-mono"] .portal-tracking-progress,
[data-theme="dark-mono"] .portal-tracking-detail-grid div,
[data-theme="dark-mono"] .portal-contract-health-meta div,
[data-theme="dark-mono"] .portal-soft-empty,
[data-theme="dark-mono"] .portal-precheck-grid article {
    background: rgba(2, 6, 23, .48);
    border-color: rgba(148, 163, 184, .16);
}

[data-theme="dark-mono"] .portal-role-focus-card small,
[data-theme="dark-mono"] .portal-role-focus-card em,
[data-theme="dark-mono"] .portal-tracking-overview span,
[data-theme="dark-mono"] .portal-contract-summary span,
[data-theme="dark-mono"] .portal-calendar-summary span,
[data-theme="dark-mono"] .portal-contract-finance-strip span,
[data-theme="dark-mono"] .portal-tracking-overview p,
[data-theme="dark-mono"] .portal-contract-summary p,
[data-theme="dark-mono"] .portal-calendar-summary small,
[data-theme="dark-mono"] .portal-contract-summary small,
[data-theme="dark-mono"] .portal-tracking-card p,
[data-theme="dark-mono"] .portal-tracking-card small,
[data-theme="dark-mono"] .portal-tracking-detail-grid span,
[data-theme="dark-mono"] .portal-tracking-detail-grid small,
[data-theme="dark-mono"] .portal-contract-health-card p,
[data-theme="dark-mono"] .portal-contract-health-meta span,
[data-theme="dark-mono"] .portal-soft-empty,
[data-theme="dark-mono"] .portal-precheck-card p,
[data-theme="dark-mono"] .portal-precheck-grid span,
[data-theme="dark-mono"] .portal-precheck-grid small {
    color: #cbd5e1;
}

[data-theme="dark-mono"] .portal-precheck-card h2,
[data-theme="dark-mono"] .portal-precheck-grid strong {
    color: #e2e8f0;
}

@media (max-width: 1180px) {
    .portal-role-focus-grid,
    .portal-tracking-overview,
    .portal-contract-summary,
    .portal-calendar-summary,
    .portal-calendar-section-grid,
    .portal-precheck-card {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .portal-tracking-overview .primary,
    .portal-contract-summary .primary,
    .portal-calendar-summary .primary {
        grid-column: 1 / -1;
    }
}

@media (max-width: 760px) {
    .portal-web-user-name {
        max-width: 150px;
    }

    .portal-web-role-chip {
        display: none;
    }

    .portal-role-focus-grid,
    .portal-tracking-overview,
    .portal-contract-summary,
    .portal-calendar-summary,
    .portal-contract-finance-strip,
    .portal-calendar-section-grid,
    .portal-tracking-detail-grid,
    .portal-contract-health-meta,
    .portal-precheck-card,
    .portal-precheck-grid,
    .portal-admin-workqueue-grid {
        grid-template-columns: 1fr;
    }

    .portal-tracking-hero,
    .portal-contract-hero,
    .portal-calendar-hero {
        align-items: start;
        grid-template-columns: auto minmax(0, 1fr);
    }

    .portal-hero-action,
    .portal-hero-proof {
        grid-column: 1 / -1;
        justify-self: start;
    }

    .portal-tracking-stage-strip {
        border-radius: 22px;
        grid-template-columns: 1fr;
    }

    .portal-tracking-card header {
        display: grid;
    }

    .portal-tracking-note {
        align-items: flex-start;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
    }

    .portal-tracking-note a {
        grid-column: 2;
        justify-self: start;
    }
}

/* ==================================================
   ORANGE SYSTEM OVERRIDE
   Palet tunggal sesuai referensi:
   #F97316, #FB923C, #FBBF24, #FDE68A, #FEFBEE, #111827.
   Role dibedakan melalui struktur dan konten, bukan warna pelangi.
   ================================================== */

:root {
    --ib-orange: #F97316;
    --ib-orange-soft: #FB923C;
    --ib-amber: #FBBF24;
    --ib-cream: #FEFBEE;
    --ib-cream-strong: #FFF7ED;
    --ib-line: #FED7AA;
    --ib-ink: #111827;
    --ib-muted: #6B7280;
    --ib-card: #FFFFFF;
}

.portal-mobile-topbar,
.portal-web-topbar {

    border-color: rgba(249, 115, 22, .18) !important;
}

.portal-web-brand-mark,
.public-brand span,
.auth-logo,
.portal-role-portal-customer .portal-web-brand-mark,
.portal-role-portal-mandor .portal-web-brand-mark,
.portal-role-portal-pt .portal-web-brand-mark {
    background: linear-gradient(135deg, var(--ib-orange), var(--ib-amber)) !important;
    box-shadow: 0 16px 32px rgba(249, 115, 22, .22) !important;
    color: #fff !important;
}

.portal-mobile-kicker,
.public-eyebrow,
.public-order-card > span,
.portal-home-kicker,
.portal-command-kicker,
.portal-source-pill,
.portal-web-role-chip {
    color: #9A3412 !important;
}

.portal-web-nav a,
.public-nav a,
.portal-home-panel,
.portal-home-metric-row article,
.portal-home-action-grid a,
.portal-home-action-band a,
.portal-home-alert,
.portal-home-list article,
.portal-feature-card,
.portal-action-row,
.portal-rule-item,
.portal-ledger-card,
.portal-tracking-card,
.portal-calendar-card,
.portal-command-card,
.portal-command-action,
.portal-workflow-panel,
.portal-precheck-card,
.portal-blocked-state,
.public-role-card,
.public-integrated-strip,
.public-final-cta,
.public-rule-list article,
.auth-card {
    background: rgba(255, 255, 255, .96) !important;
    border-color: rgba(249, 115, 22, .18) !important;
    box-shadow: 0 16px 36px rgba(17, 24, 39, .06) !important;
}

.portal-web-nav a.active,
.portal-role-portal-customer .portal-web-nav a.active,
.portal-role-portal-mandor .portal-web-nav a.active,
.portal-role-portal-pt .portal-web-nav a.active,
.public-nav-login,
.public-primary-action,
.portal-primary-action,
.portal-action-link,
.portal-hero-action,
.portal-hero-proof,
.app-btn-primary,
.btn.app-btn-primary {
    background: var(--ib-orange) !important;
    border-color: var(--ib-orange) !important;
    color: #fff !important;
    box-shadow: 0 16px 34px rgba(249, 115, 22, .24) !important;
}

.portal-web-nav a:hover,
.public-nav a:hover,
.public-secondary-action:hover,
.portal-secondary-action:hover,
.portal-home-panel-head a:hover {
    border-color: var(--ib-orange-soft) !important;
    color: var(--ib-ink) !important;
}

.public-secondary-action,
.portal-secondary-action,
.portal-home-secondary,
.portal-home-panel-head a,
.portal-home-soft-pill,
.portal-action-link.secondary,
.portal-status-pill,
.portal-hero-status,
.portal-chip-row span,
.public-step-row span {
    background: var(--ib-cream-strong) !important;
    border-color: var(--ib-line) !important;
    color: #9A3412 !important;
}

.public-hero,
.portal-feature-hero,
.portal-command-hero,
.portal-command-customer .portal-command-hero,
.portal-command-mandor .portal-command-hero,
.portal-command-pt .portal-command-hero,
.portal-workflow-hero,
.portal-ledger-hero,
.portal-directory-hero,
.portal-service-hero,
.portal-order-hero,
.portal-finance-hero,
.portal-tracking-hero,
.portal-contract-hero,
.portal-calendar-hero,
.portal-care-hero,
.portal-home-hero,
.portal-home-hero.customer,
.portal-home-hero.mandor,
.portal-home-hero.pt {
    background:
        radial-gradient(circle at 82% 16%, rgba(251, 191, 36, .36), transparent 28%),
        linear-gradient(135deg, var(--ib-ink) 0%, #7C2D12 48%, var(--ib-orange) 100%) !important;
    color: #fff !important;
    box-shadow: 0 24px 58px rgba(17, 24, 39, .16) !important;
}

.public-hero h1,
.public-hero p,
.portal-feature-hero h1,
.portal-feature-hero p,
.portal-home-hero h1,
.portal-home-hero p,
.portal-command-hero h1,
.portal-command-hero p {
    color: #fff !important;
}

.portal-home-secondary {

    border-color: rgba(255,255,255,.42) !important;

}

.portal-home-flow-card,
.portal-home-balance-card,
.portal-pt-executive-card,
.public-order-card {

    border-color: rgba(255, 255, 255, .30) !important;
}

.portal-customer-flow article.done,
.public-order-flow i,
.portal-home-action-grid i,
.portal-home-action-band i,
.portal-home-panel-head > i,
.portal-home-list i,
.portal-command-action > i,
.portal-action-row i:first-child,
.portal-rule-item i,
.portal-record-icon,
.public-role-card > i {
    background: var(--ib-cream-strong) !important;
    border-color: var(--ib-line) !important;
    color: var(--ib-orange) !important;
}

.portal-command-action.tone-green > i,
.portal-command-action.tone-blue > i,
.portal-command-action.tone-orange > i,
.portal-command-action.tone-purple > i,
.portal-command-action.tone-slate > i,
.portal-command-action.tone-red > i {
    background: var(--ib-cream-strong) !important;
    border-color: var(--ib-line) !important;
    color: var(--ib-orange) !important;
}

.portal-home-alert,
.portal-home-alert.level-warning,
.portal-home-alert.level-danger,
.portal-precheck-card,
.portal-precheck-card.tone-green,
.portal-precheck-card.tone-orange,
.portal-precheck-card.tone-red,
.portal-home-rule-note,
.portal-mobile-alert {
    background: var(--ib-cream-strong) !important;
    border-color: var(--ib-line) !important;
    border-left-color: var(--ib-orange) !important;
    color: #9A3412 !important;
}

.portal-home-metric-row strong,
.portal-home-panel-head h2,
.portal-home-list strong,
.portal-home-list b,
.portal-home-mini-ledger strong,
.portal-home-scope-grid strong,
.portal-ledger-summary strong,
.portal-precheck-grid strong,
.portal-tracking-overview strong,
.portal-contract-summary strong,
.portal-calendar-summary strong,
.public-role-card h2,
.public-integrated-strip h2,
.public-final-cta h2,
.auth-card h5 {
    color: var(--ib-ink) !important;
}

.portal-home-metric-row span,
.portal-home-mini-ledger span,
.portal-home-scope-grid span,
.portal-section-heading span,
.portal-feature-card p,
.portal-home-list small,
.portal-home-action-grid small,
.portal-home-action-band small,
.portal-muted-note,
.public-role-card p,
.public-final-cta p,
.auth-card p,
.form-text {
    color: var(--ib-muted) !important;
}

.portal-form-grid input,
.portal-form-grid select,
.portal-form-grid textarea,
.app-input,
.form-control,
.form-select {
    background: #fff !important;
    border-color: rgba(249, 115, 22, .24) !important;
    color: var(--ib-ink) !important;
}

.portal-form-grid input:focus,
.portal-form-grid select:focus,
.portal-form-grid textarea:focus,
.app-input:focus,
.form-control:focus,
.form-select:focus {
    border-color: var(--ib-orange) !important;
    box-shadow: 0 0 0 .2rem rgba(249, 115, 22, .16) !important;
}

.portal-tracking-stage-strip,
.portal-order-progress,
.portal-workflow-steps,
.portal-order-live-preview,
.portal-finance-proof-strip,
.portal-ledger-summary,
.portal-role-focus-card,
.portal-contract-finance-strip {
    background: rgba(255, 247, 237, .88) !important;
    border-color: var(--ib-line) !important;
}

.portal-workflow-steps .is-active,
.portal-order-progress .is-active,
.portal-tracking-stage-strip .is-active {
    background: #fff !important;
    border-color: var(--ib-orange-soft) !important;
    color: var(--ib-orange) !important;
}

[data-theme="dark-mono"] .portal-mobile-body,
[data-theme="dark-mono"] .portal-web-body,
[data-theme="dark-mono"] .is-public {
    background: linear-gradient(180deg, #0B0F19 0%, #111827 58%, #1C1917 100%) !important;
    color: #FEFBEE !important;
}

[data-theme="dark-mono"] .portal-mobile-topbar,
[data-theme="dark-mono"] .portal-web-topbar {
    background: rgba(17, 24, 39, .94) !important;
