    --ib7-cream-2: #FFF7ED;
    --ib7-muted: rgba(17, 24, 39, .68);
    --ib7-shadow: 0 18px 42px rgba(17, 24, 39, .08);
    --ib7-shadow-soft: 0 10px 24px rgba(17, 24, 39, .06);

    --secondary: var(--ib7-white) !important;
    --secondary-hover: var(--ib7-cream-2) !important;
    --secondary-text: var(--ib7-ink) !important;

    --success-soft: var(--ib7-cream-2) !important;

    --warning-soft: var(--ib7-cream) !important;

    --danger-soft: var(--ib7-cream-2) !important;

    --info-soft: var(--ib7-cream-2) !important;

    --border: var(--ib7-line) !important;
    --border-soft: rgba(249, 115, 22, .14) !important;
