    --surface: var(--ib7-white) !important;
    --surface-soft: var(--ib7-cream) !important;
    --surface-muted: var(--ib7-cream-2) !important;
    --bg: var(--ib7-cream) !important;
    --bg-soft: var(--ib7-cream-2) !important;
}

