}

/* 10. Print/report pages should not depend on screen-only wrappers. */
@media print {
    .app-table {
        min-width: 0 !important;
        width: 100% !important;
    }

    .app-table :where(th, td) {
        white-space: normal !important;
    }

    .app-table th:last-child,
    .app-table td:last-child {
        min-width: 0 !important;
        text-align: inherit !important;
    }
}

@media (max-width: 991.98px) {
    body.is-authenticated .content-area table.app-table {
