    }

    body.is-authenticated .portal-home :where(.portal-home-metric-row, .portal-home-action-band, .portal-home-grid, .portal-home-grid.two) {
        grid-template-columns: 1fr !important;
    }

    body.is-authenticated .content-area .customer-success-summary-grid {
        grid-template-columns: 1fr;
    }

    body.is-authenticated .content-area .customer-success-card-header {
        flex-direction: column;
    }
}

