/*
   Portal Executive Polish Lock
   A cleaner, calmer portal layer after the broad density pass.
   Goal: remove the orange-outline overload and make customer/mandor/PT portal feel finished.
*/

:root {
    --portal-ex-bg: #f7f8fa;
    --portal-ex-surface: #ffffff;
    --portal-ex-panel: #ffffff;
    --portal-ex-soft: #f8fafc;
    --portal-ex-accent-soft: #fff7ed;
    --portal-ex-line: #e5e7eb;
    --portal-ex-line-strong: #d1d5db;
    --portal-ex-text: #111827;
    --portal-ex-muted: #4b5563;
    --portal-ex-subtle: #6b7280;
    --portal-ex-primary: #ea580c;
    --portal-ex-primary-dark: #c2410c;
    --portal-ex-primary-soft: #ffedd5;
    --portal-ex-danger: #b91c1c;
    --portal-ex-danger-soft: #fff1f2;
    --portal-ex-warning: #92400e;
    --portal-ex-warning-soft: #fffbeb;
    --portal-ex-info: #1d4ed8;
    --portal-ex-info-soft: #eff6ff;
    --portal-ex-success: #166534;
    --portal-ex-success-soft: #f0fdf4;
    --portal-ex-radius: 14px;
    --portal-ex-radius-sm: 10px;
    --portal-ex-shadow: 0 14px 40px rgba(15, 23, 42, .07);
    --portal-ex-shadow-sm: 0 1px 2px rgba(15, 23, 42, .05);
}

body.portal-mobile-body,
body.portal-web-body {

    color: var(--portal-ex-text) !important;
