/*
   Global Layout Balance Lock
   Purpose: final visual balance pass for crowded ERP/portal screens.
   Scope: CSS only. No business logic, route, transaction, ERP, or database changes.
*/

:root {
    --balance-page: #f8fafc;
    --balance-surface: #ffffff;
    --balance-soft: #f1f5f9;
    --balance-soft-2: #f9fafb;
    --balance-line: #e2e8f0;
    --balance-line-strong: #cbd5e1;
    --balance-text: #0f172a;
    --balance-muted: #475569;
    --balance-faint: #64748b;
    --balance-primary: #ea580c;
    --balance-primary-hover: #c2410c;
    --balance-danger: #b91c1c;
    --balance-success: #166534;
    --balance-warning: #92400e;
    --balance-info: #1d4ed8;
    --balance-radius: 12px;
    --balance-radius-sm: 8px;
    --balance-shadow: 0 1px 2px rgba(15, 23, 42, .04);
    --balance-shadow-hover: 0 10px 22px rgba(15, 23, 42, .07);
}

body :where(
    .app-shell,
    .main-content,
    .content-wrapper,
    .app-main,
    .portal-web-content,
    .portal-mobile-content,
    .portal-home,
    .auth-page,
    .public-page
) {
    background: var(--balance-page) !important;
}

body :where(
    .page-header,
    .app-page-header,
    .app-card,
    .card,
    .content-card,
    .panel,
    .dashboard-card,
    .dashboard-panel,
    .kpi-card,
    .summary-card,
    .app-stat-card,
    .metric-card,
    .portal-home-hero,
    .portal-home-panel,
    .portal-home-flow-card,
    .portal-home-alert,
    .portal-home-metric-row > article,
    .portal-home-action-grid a,
    .portal-home-action-band a,
    .portal-home-list article,
    .portal-home-mini-ledger div,
    .auth-card,
    .modal-content
) {
    background: var(--balance-surface) !important;
    background-image: none !important;
    border: 1px solid var(--balance-line) !important;
    border-radius: var(--balance-radius) !important;
    box-shadow: var(--balance-shadow) !important;
    color: var(--balance-text) !important;
}

body :where(.card:hover, .app-card:hover, .portal-home-action-grid a:hover, .portal-home-action-band a:hover) {
    box-shadow: var(--balance-shadow-hover) !important;
}

body :where(h1, h2, h3, h4, h5, h6, strong, b, .fw-bold) {
    color: var(--balance-text) !important;
    letter-spacing: 0 !important;
}

body :where(p, small, .small, .text-muted, .text-secondary, .form-text, .app-muted, .portal-mobile-kicker) {
    color: var(--balance-muted) !important;
}

/* Page density */
.container,
.container-fluid {
    max-width: 1400px !important;
}

.container.py-4,
.container-fluid.py-4,
.app-content,
.content {

    padding-bottom: 36px !important;
}

.page-header,
.app-page-header {
