/*
   Global Flash Toast Redesign Lock
   Replaces the centered/bootstrap-alert feel with a compact app toast:
   smaller shape, white surface, subtle accent, clean icon, close control,
   and slide/fade animation. CSS only.
*/

:root {
    --gtr-surface: #ffffff;
    --gtr-text: #111827;
    --gtr-muted: #64748b;
    --gtr-line: #e2e8f0;
    --gtr-success: #16a34a;
    --gtr-success-soft: #ecfdf5;
    --gtr-info: #2563eb;
    --gtr-info-soft: #eff6ff;
    --gtr-warning: #d97706;
    --gtr-warning-soft: #fffbeb;
    --gtr-danger: #dc2626;
    --gtr-danger-soft: #fef2f2;
    --gtr-shadow: 0 10px 28px rgba(15, 23, 42, .12);
}

.app-flash-center-host {
    position: fixed !important;
    inset: auto 18px 18px auto !important;
    z-index: 2140 !important;
    width: auto !important;
    height: auto !important;
    max-width: calc(100vw - 36px) !important;
    display: block !important;
    padding: 0 !important;
    pointer-events: none !important;
}

.app-flash-center-stack {
    width: min(360px, calc(100vw - 36px)) !important;
    max-height: min(70vh, 520px) !important;
    display: grid !important;
    gap: 8px !important;
    overflow: visible !important;
    pointer-events: auto !important;
}

.app-alert.app-flash-centered {
    --gtr-tone: var(--gtr-info);
    --gtr-tone-soft: var(--gtr-info-soft);
    width: 100% !important;
    min-height: 48px !important;
    margin: 0 !important;
    padding: 10px 38px 10px 44px !important;
    position: relative !important;
    display: block !important;
    border-radius: 9px !important;
    border: 1px solid var(--gtr-line) !important;
    border-left: 3px solid var(--gtr-tone) !important;
    background: var(--gtr-surface) !important;
    background-image: none !important;
    color: var(--gtr-text) !important;
    box-shadow: var(--gtr-shadow) !important;
    font-size: .92rem !important;
    font-weight: 600 !important;
    line-height: 1.35 !important;
    letter-spacing: 0 !important;
    overflow: hidden !important;
    animation: gtrToastIn 180ms cubic-bezier(.2, .8, .2, 1) both !important;
}

.app-alert.app-flash-centered::before {
    content: "" !important;
    position: absolute !important;
    inset: 0 auto 0 0 !important;
    width: 0 !important;
    background: transparent !important;
}

.app-alert.app-flash-centered::after {
    content: "i" !important;
    width: 24px !important;
    height: 24px !important;
    position: absolute !important;
    left: 12px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: 7px !important;
    background: var(--gtr-tone-soft) !important;
    color: var(--gtr-tone) !important;
    font-size: .84rem !important;
    font-weight: 700 !important;
    line-height: 1 !important;
}

.app-alert.app-flash-centered.alert-success {
    --gtr-tone: var(--gtr-success);
    --gtr-tone-soft: var(--gtr-success-soft);
}

.app-alert.app-flash-centered.alert-success::after {
    content: "✓" !important;
}

.app-alert.app-flash-centered.alert-warning {
    --gtr-tone: var(--gtr-warning);
    --gtr-tone-soft: var(--gtr-warning-soft);
}

.app-alert.app-flash-centered.alert-warning::after {
    content: "!" !important;
}

.app-alert.app-flash-centered.alert-danger,
.app-alert.app-flash-centered.alert-error {
    --gtr-tone: var(--gtr-danger);
    --gtr-tone-soft: var(--gtr-danger-soft);
}

.app-alert.app-flash-centered.alert-danger::after,
.app-alert.app-flash-centered.alert-error::after {
    content: "!" !important;
}

.app-alert.app-flash-centered .app-flash-message-text {
    display: block !important;
    min-width: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    color: var(--gtr-text) !important;
    font-size: .92rem !important;
    font-weight: 600 !important;
    line-height: 1.35 !important;
    overflow-wrap: anywhere !important;
}

.app-alert.app-flash-centered .btn-close {
    width: 22px !important;
    height: 22px !important;
    min-width: 22px !important;
    min-height: 22px !important;
    position: absolute !important;
    top: 50% !important;
    right: 9px !important;
    transform: translateY(-50%) !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 6px !important;
    background-color: transparent !important;
    box-shadow: none !important;
    opacity: .5 !important;
}

.app-alert.app-flash-centered .btn-close:hover,
.app-alert.app-flash-centered .btn-close:focus-visible {
    background-color: rgba(15, 23, 42, .07) !important;
    opacity: .82 !important;
    outline: none !important;
    box-shadow: none !important;
}

.app-alert.app-flash-centered.is-hiding {
    animation: gtrToastOut 150ms ease-in forwards !important;
}

@keyframes gtrToastIn {
    from {
        opacity: 0;
        transform: translate3d(18px, 10px, 0) scale(.98);
    }
    to {
        opacity: 1;
        transform: translate3d(0, 0, 0) scale(1);
    }
}

@keyframes gtrToastOut {
    from {
        opacity: 1;
        transform: translate3d(0, 0, 0) scale(1);
    }
    to {
        opacity: 0;
        transform: translate3d(16px, 8px, 0) scale(.98);
    }
}

@media (max-width: 720px) {
    .app-flash-center-host {
        inset: 12px 12px auto 12px !important;
        max-width: none !important;
    }

    .app-flash-center-stack {
        width: 100% !important;
    }

    .app-alert.app-flash-centered {
        min-height: 46px !important;
        padding: 10px 36px 10px 42px !important;
        border-radius: 9px !important;
        font-size: .9rem !important;
    }
}

@media (prefers-reduced-motion: reduce) {
    .app-alert.app-flash-centered,
    .app-alert.app-flash-centered.is-hiding {
        animation: none !important;
    }
}

